package com.citi.put.checks.studio.secrets;

import java.net.URI;
import java.net.URISyntaxException;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;

/**
 * The origins a secret may be filled on, as its own vault entry declares them.
 *
 * <p>A secret's KV v2 entry carries an {@value #VAULT_KEY} key next to its value: a comma-separated
 * list such as {@code https://login.app.example,https://sso.app.example}, owned by whoever owns the
 * secret. The runner refuses to type the secret on a page whose origin is not in the list ({@code
 * SECRET_ORIGIN_NOT_ALLOWED}).
 *
 * <p>Each entry is normalized to the form a browser's {@code URL.origin} renders — {@code
 * scheme://host[:port]}, lowercase scheme and host, default port dropped — so the runner can
 * compare with string equality. Only {@code http} and {@code https} are accepted, and an entry
 * carrying a path, query, fragment or user info is not an origin.
 *
 * <p><b>Fail closed.</b> One malformed entry makes the whole list empty rather than dropping that
 * entry: a list the owner wrote wrongly is not a list anyone can reason about, and an empty list
 * means the secret cannot be filled anywhere. The same holds for an over-long list.
 */
public final class SecretOrigins {

  /** The key, next to the value key, that holds the comma-separated origins. */
  public static final String VAULT_KEY = "allowedOrigins";

  /** Upper bound on origins per secret. Matches the runner's envelope bound. */
  public static final int MAX_ORIGINS = 16;

  /** Upper bound on one entry's length. Matches the runner's envelope bound. */
  public static final int MAX_ORIGIN_LENGTH = 512;

  private SecretOrigins() {}

  /**
   * Parses and normalizes a comma-separated origin list.
   *
   * @param raw the stored list, possibly {@code null}
   * @return the normalized, de-duplicated origins in declared order, or an empty list when {@code
   *     raw} is absent, blank or malformed in any entry
   */
  public static List<String> parse(String raw) {
    if (raw == null || raw.isBlank()) {
      return List.of();
    }
    Set<String> origins = new LinkedHashSet<>();
    for (String entry : raw.split(",", -1)) {
      String normalized = normalize(entry.strip());
      if (normalized == null) {
        return List.of();
      }
      origins.add(normalized);
    }
    return origins.size() > MAX_ORIGINS ? List.of() : List.copyOf(origins);
  }

  private static String normalize(String candidate) {
    if (candidate.isEmpty() || candidate.length() > MAX_ORIGIN_LENGTH) {
      return null;
    }
    URI uri;
    try {
      uri = new URI(candidate);
    } catch (URISyntaxException e) {
      return null;
    }
    String scheme = uri.getScheme() == null ? null : uri.getScheme().toLowerCase(Locale.ROOT);
    if (!"http".equals(scheme) && !"https".equals(scheme)) {
      return null;
    }
    String path = uri.getRawPath();
    boolean hasPath = path != null && !path.isEmpty() && !"/".equals(path);
    if (uri.getRawUserInfo() != null
        || uri.getRawQuery() != null
        || uri.getRawFragment() != null
        || hasPath) {
      return null;
    }
    String host = uri.getHost();
    if (host == null || host.isEmpty()) {
      return null;
    }
    int port = uri.getPort();
    if (port == 0 || port > 65_535) {
      return null;
    }
    int defaultPort = "https".equals(scheme) ? 443 : 80;
    String authority = host.toLowerCase(Locale.ROOT);
    if (port != -1 && port != defaultPort) {
      authority = authority + ':' + port;
    }
    return scheme + "://" + authority;
  }
}
package com.citi.put.checks.studio.secrets;

import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.databind.JsonSerializer;
import com.fasterxml.jackson.databind.SerializerProvider;
import java.io.IOException;
import java.util.Arrays;
import java.util.Objects;

/** Owned ephemeral secret buffer; neither diagnostics nor accidental bean access reveals it. */
public final class SecretValue implements AutoCloseable {
  @com.fasterxml.jackson.annotation.JsonIgnore
  private final char[] value;
  @com.fasterxml.jackson.annotation.JsonIgnore
  private boolean erased;

  /** Takes ownership of the caller's buffer, including responsibility for erasure. */
  public SecretValue(char[] value) {
    this.value = Objects.requireNonNull(value);
  }

  public int length() {
    return value.length;
  }

  /** Compares transient artifact literals without constructing a secret String. */
  public boolean matches(String candidate) {
    if (erased || candidate == null || candidate.length() != value.length) return false;
    int difference = 0;
    for (int i = 0; i < value.length; i++) difference |= value[i] ^ candidate.charAt(i);
    return difference == 0;
  }

  @Override
  public String toString() {
    return "<secret>";
  }

  @Override
  public void close() {
    Arrays.fill(value, '\0');
    erased = true;
  }

  /** The sole secret-bearing JSON writer. Always erases, including generator failures. */
  public static final class Writer extends JsonSerializer<SecretValue> {
    @Override
    public void serialize(SecretValue secret, JsonGenerator generator, SerializerProvider provider)
        throws IOException {
      if (secret.erased) throw new IOException("Secret buffer was already erased");
      try {
        generator.writeString(secret.value, 0, secret.value.length);
      } finally {
        secret.close();
      }
    }
  }
}
package com.citi.put.checks.studio.secrets;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.module.SimpleModule;
import java.io.IOException;

/** Explicit opt-in writer for the two credential-bearing channels; never the application mapper. */
public final class SecretWireWriter {
  private SecretWireWriter() {}

  public static byte[] bytes(ObjectMapper mapper, Object body) throws IOException {
    var module = new SimpleModule("StudioSecretWire");
    module.addSerializer(SecretValue.class, new SecretValue.Writer());
    return mapper.copy().registerModule(module).writeValueAsBytes(body);
  }
}
package com.citi.put.checks.studio.secrets;

import com.citi.put.checks.security.CsiOwnershipEvaluator;
import com.citi.put.checks.studio.StudioAccessDeniedException;
import com.citi.put.checks.studio.StudioRepository;
import com.citi.put.checks.studio.StudioValidationException;
import com.citi.put.checks.studio.entity.UITest;
import com.fasterxml.jackson.core.StreamReadFeature;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.cfg.CoercionAction;
import com.fasterxml.jackson.databind.cfg.CoercionInputShape;
import com.fasterxml.jackson.databind.type.LogicalType;
import java.io.IOException;
import java.util.Arrays;
import java.util.List;
import java.util.UUID;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.context.annotation.Profile;
import org.springframework.security.core.Authentication;
import org.springframework.stereotype.Service;

/**
 * Saves and lists one test's Studio secrets, in Vault only (studio-vault-secrets FR-1, FR-3, FR-4).
 *
 * <p><b>Scope comes from the row.</b> The CSI, the environment and the test id of every Vault path
 * are read from the persisted {@code ui_tests} row, loaded through the same visibility-restricted
 * lookup save and delete use. Nothing in a request can name them.
 *
 * <p><b>Authorization first.</b> Listing needs {@code canRead} on the test's CSI; creating needs
 * {@code canWrite}. An absent test and a denied CSI are the same {@link
 * StudioAccessDeniedException}. The create body is parsed only <em>after</em> that decision, so an
 * unauthorized caller learns nothing about name validity or Vault state from a {@code 400}, {@code
 * 409} or {@code 503}.
 *
 * <p><b>The value.</b> It is parsed straight from the received bytes into a {@code char[]}, never
 * through a {@link String}, and both the body bytes and the value are zero-filled on every exit
 * path. No error message carries it and no parser message is echoed. The residual, stated rather
 * than implied (the same stance as {@code StudioReferenceResolver.Resolved}): Jackson's recycled
 * parse buffers and the servlet container's and HTTP client's transient buffers can still hold
 * bytes of it until they are reused. What is claimed is that nothing here retains a reference.
 *
 * <p>Not transactional on purpose: the only database touch is the row lookup, and no connection is
 * held across the Vault call.
 */
@Service
@Profile("!worker")
public class StudioSecretsService {

  private static final Logger LOGGER = LoggerFactory.getLogger(StudioSecretsService.class);

  /** Upper bound on a create body, checked after authorization. */
  static final int MAX_BODY_BYTES = 64 * 1024;

  /**
   * Upper bound on a value, in UTF-16 units. With the worst-case JSON escaping and the origin list,
   * a stored entry stays under the 64 KiB read cap it must later be read back through.
   */
  static final int MAX_VALUE_LENGTH = 4096;

  static final String INVALID_REQUEST = "INVALID_SECRET_REQUEST";
  static final String INVALID_NAME = "INVALID_SECRET_NAME";
  static final String INVALID_VALUE = "INVALID_SECRET_VALUE";
  static final String INVALID_ORIGINS = "INVALID_SECRET_ORIGINS";

  private final StudioRepository studioRepository;
  private final CsiOwnershipEvaluator csiOwnershipEvaluator;
  private final StudioVaultProvider vault;
  private final ObjectMapper strict;

  public StudioSecretsService(
      StudioRepository studioRepository,
      CsiOwnershipEvaluator csiOwnershipEvaluator,
      StudioVaultProvider vault,
      ObjectMapper platformMapper) {
    this.studioRepository = studioRepository;
    this.csiOwnershipEvaluator = csiOwnershipEvaluator;
    this.vault = vault;
    this.strict = strictCopyOf(platformMapper);
  }

  /**
   * The platform mapper, closed for this one boundary: unknown fields, trailing tokens, a single
   * string where a list is declared, and a number or boolean where text is declared are all
   * refused, and so is a duplicated key, so a body carrying two {@code value}s is not silently read
   * as one of them. The platform mapper itself is left unchanged.
   *
   * <p>A value Jackson has already materialized when a later token fails the parse is dropped with
   * the partial record and cannot be erased here; like the parser's own buffers, that copy is left
   * to the garbage collector.
   */
  static ObjectMapper strictCopyOf(ObjectMapper platformMapper) {
    ObjectMapper strict =
        platformMapper
            .copy()
            .enable(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES)
            .enable(DeserializationFeature.FAIL_ON_TRAILING_TOKENS)
            .disable(DeserializationFeature.ACCEPT_SINGLE_VALUE_AS_ARRAY);
    strict.getFactory().enable(StreamReadFeature.STRICT_DUPLICATE_DETECTION.mappedFeature());
    for (CoercionInputShape shape :
        List.of(CoercionInputShape.Integer, CoercionInputShape.Float, CoercionInputShape.Boolean)) {
      strict.coercionConfigFor(LogicalType.Textual).setCoercion(shape, CoercionAction.Fail);
    }
    return strict;
  }

  /** The names stored for a test the caller may read. Names only. */
  public StudioSecretListDto list(UUID testId, Authentication auth) {
    UITest test = studioRepository.findById(testId).orElseThrow(StudioAccessDeniedException::new);
    if (test.getCsiId() == null || !csiOwnershipEvaluator.canRead(auth, test.getCsiId())) {
      throw new StudioAccessDeniedException();
    }
    return new StudioSecretListDto(
        vault.listSecretNames(scopeOf(test)).stream().map(StudioSecretNameDto::new).toList());
  }

  /**
   * Stores a new secret for a test the caller may write, create-only.
   *
   * <p>In order: authorization ({@code 403}), then the body ({@code 400}), then Vault ({@code 409}
   * or {@code 503}). {@code body} is erased before this returns or throws.
   */
  public StudioSecretDto create(UUID testId, byte[] body, Authentication auth) {
    CreateStudioSecretRequest request = null;
    try {
      UITest test = studioRepository.findById(testId).orElseThrow(StudioAccessDeniedException::new);
      if (test.getCsiId() == null || !csiOwnershipEvaluator.canWrite(auth, test.getCsiId())) {
        throw new StudioAccessDeniedException();
      }

      request = parse(body);
      String name = validName(request.name());
      validateValue(request.value());
      List<String> origins = validOrigins(request.allowedOrigins());

      String version = vault.create(scopeOf(test), name, request.value(), origins);
      LOGGER.info("Studio secret created: test={} name={} version={}", testId, name, version);
      return new StudioSecretDto(name, version, origins);
    } finally {
      if (body != null) {
        Arrays.fill(body, (byte) 0);
      }
      if (request != null && request.value() != null) {
        Arrays.fill(request.value(), '\0');
      }
    }
  }

  private CreateStudioSecretRequest parse(byte[] body) {
    if (body == null || body.length == 0 || body.length > MAX_BODY_BYTES) {
      throw invalidRequest();
    }
    CreateStudioSecretRequest request;
    try {
      // Straight from the bytes: never `new String(body)`, which would be an unerasable copy.
      request = strict.readValue(body, CreateStudioSecretRequest.class);
    } catch (IOException e) {
      // The parser's message is not echoed: it can quote the input, and the input is a secret.
      throw invalidRequest();
    }
    if (request == null) {
      throw invalidRequest();
    }
    return request;
  }

  private static String validName(String name) {
    if (!StudioVaultProvider.isValidSecretName(name)) {
      throw new StudioValidationException(
          INVALID_NAME,
          "name must be 1 to 64 characters of A-Z, a-z, 0-9, '_', '.' or '-', and not '.' or '..'");
    }
    return name;
  }

  private static void validateValue(char[] value) {
    if (value == null || value.length == 0 || value.length > MAX_VALUE_LENGTH) {
      throw new StudioValidationException(
          INVALID_VALUE,
          "value is required and must be at most " + MAX_VALUE_LENGTH + " characters");
    }
  }

  /**
   * Each entry is normalized by {@link SecretOrigins}, the same normalizer the reader uses, and the
   * normalized list is what is stored. An entry that does not survive normalization one-for-one — a
   * malformed origin, a duplicate, or an entry smuggling a comma — refuses the whole list.
   */
  private static List<String> validOrigins(List<String> origins) {
    if (origins == null
        || origins.isEmpty()
        || origins.size() > SecretOrigins.MAX_ORIGINS
        || origins.stream()
            .anyMatch(
                origin -> origin == null || origin.length() > SecretOrigins.MAX_ORIGIN_LENGTH)) {
      throw invalidOrigins();
    }
    List<String> normalized = SecretOrigins.parse(String.join(",", origins));
    if (normalized.size() != origins.size()) {
      throw invalidOrigins();
    }
    return normalized;
  }

  private static VaultScope scopeOf(UITest test) {
    return VaultScope.of(test.getCsiId(), test.getEnvironment(), test.getId());
  }

  private static StudioValidationException invalidRequest() {
    return new StudioValidationException(
        INVALID_REQUEST,
        "The body must be a JSON object with exactly name, value and allowedOrigins");
  }

  private static StudioValidationException invalidOrigins() {
    return new StudioValidationException(
        INVALID_ORIGINS,
        "allowedOrigins must list 1 to "
            + SecretOrigins.MAX_ORIGINS
            + " distinct http(s) origins of at most "
            + SecretOrigins.MAX_ORIGIN_LENGTH
            + " characters, with no path, query or credentials");
  }
}
package com.citi.put.checks.studio.secrets;

import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;

/**
 * The development entitlement policy behind {@link StudioSecretUseAuthorization} (AC-4, AC-5a).
 *
 * <p>This is <b>development configuration</b>, keyed {@code principal|csi|environment} and holding
 * the secret ids that principal may use there. It is not the production policy: PUT Core owns the
 * production secret-use policy (V6, CON-2), and the platform Vault's own token policy is `ED-02`'s.
 * Neither is connected on this branch, and inventing a principal entitlement model in their place
 * would be an Article IV violation. AC-5b is where the real policy, including the principal
 * dimension, is evaluated.
 *
 * <p>What this <em>does</em> give AC-4 is a decision that is genuinely separate from open execution
 * admission: the entitlement is per secret, so a principal who may start the test can still be
 * refused {@code LOGIN_PW}. That is the decision the seam exists to make.
 *
 * <p>Fail-closed at every gap: an unknown principal, an unknown CSI, an unknown environment or an
 * empty entitlement set all answer {@code false}.
 */
public final class ConfiguredSecretUseAuthorization implements StudioSecretUseAuthorization {

  private final Map<String, Set<String>> entitlements;

  public ConfiguredSecretUseAuthorization(Map<String, Set<String>> entitlements) {
    this.entitlements = Map.copyOf(entitlements);
  }

  @Override
  public boolean mayUse(String principal, String csiId, String environment, String secretId) {
    if (principal == null || csiId == null || environment == null || secretId == null) {
      return false;
    }
    return entitlements
        .getOrDefault(key(principal, csiId, environment), Set.of())
        .contains(secretId);
  }

  /** The key form, exposed so configuration and tests agree on one derivation. */
  public static String key(String principal, String csiId, String environment) {
    return principal + '|' + csiId + '|' + environment;
  }

  /** Parses {@code principal|csi|environment -> "A,B,C"} from development configuration. */
  public static Map<String, Set<String>> parse(Map<String, String> configured) {
    Map<String, Set<String>> parsed = new java.util.LinkedHashMap<>();
    configured.forEach(
        (key, value) -> {
          if (key.split("\\|", -1).length != 3) {
            throw new IllegalStateException(
                "studio.secrets.entitlements key '" + key + "' is not principal|csi|environment");
          }
          Set<String> ids = new LinkedHashSet<>();
          for (String id : value.split(",")) {
            String trimmed = id.trim();
            if (!trimmed.isEmpty()) {
              ids.add(trimmed);
            }
          }
          parsed.put(key, Set.copyOf(ids));
        });
    return Map.copyOf(parsed);
  }
}
package com.citi.put.checks.studio.secrets;

import com.citi.put.checks.studio.dispatch.ReferenceDeclarations;
import com.citi.put.checks.studio.dispatch.StudioReferenceResolver;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.UUID;
import org.springframework.stereotype.Component;

/**
 * The vault-backed resolver that replaces {@code StubStudioReferenceResolver} (AC-1, AC-4, AC-5a,
 * AC-7a).
 *
 * <p>History: the stub it replaced answered its two questions against the former global platform
 * {@code secrets} table (dropped by V25) and <b>never read its {@code csiId} parameter at all</b>,
 * so any CSI could name any secret; and it returned a configured canary string for every name, so
 * no real value had ever reached a runner. Both are gone. Vault is now the only secret store.
 *
 * <p>Three properties, all of them AC-5a's and all decidable on this branch without inventing an
 * entitlement model:
 *
 * <ul>
 *   <li>the resolvable set is the <b>confirmed revision's</b> typed declaration, handed in by the
 *       caller — never the draft's current {@code variables} and never the request;
 *   <li>the CSI is the <b>execution's own immutable</b> {@code csi_id}, so editing or moving the
 *       parent draft between acceptance and dispatch changes nothing;
 *   <li>the environment is the one snapshotted at acceptance, so a reference entitled only in
 *       {@code dev} is simply absent for a {@code prod} execution;
 *   <li>the test id scopes every read ({@link VaultScope}), so a secret saved for one test is
 *       absent for another test with the same CSI and environment.
 * </ul>
 *
 * <p>A declared secret id that is not a valid secret name ({@link
 * StudioVaultProvider#isValidSecretName}), such as a legacy {@code vault://…} id, is refused as an
 * unknown (acceptance) or unavailable (dispatch) reference <b>before</b> the provider is called.
 * Otherwise the provider's path-safety check would report it as a Vault outage.
 *
 * <p>Secret use is a decision of its own (§9.2): {@link StudioSecretUseAuthorization} is consulted
 * <b>separately</b> from {@code CsiOwnershipEvaluator}, per secret, and a principal who owns the
 * CSI can still be refused a secret it names. The principal dimension of the <em>real</em> vault's
 * policy is AC-5b and `ED-02`'s.
 *
 * <p><b>Secret preflight reads names only.</b> Authorization and the scoped name list prove the
 * declaration exists without reading its value. Legacy variable preflight erases every array it
 * reads, including on refusal.
 */
@Component
public class VaultStudioReferenceResolver implements StudioReferenceResolver {

  private final StudioVaultProvider vault;
  private final StudioSecretUseAuthorization secretUse;

  public VaultStudioReferenceResolver(
      StudioVaultProvider vault, StudioSecretUseAuthorization secretUse) {
    this.vault = vault;
    this.secretUse = secretUse;
  }

  @Override
  public void preflight(
      String csiId,
      String environment,
      UUID testId,
      String principal,
      ReferenceDeclarations declarations) {
    refuseCrossedNames(declarations, false);
    VaultScope scope = VaultScope.of(csiId, environment, testId);

    for (String name : declarations.variables()) {
      requireName(name);
      erase(
          vault
              .read(StudioVaultProvider.ReferenceKind.VARIABLE, scope, name)
              .orElseThrow(() -> new UnknownReferenceException(name)));
    }
    for (String secretId : declarations.secrets()) {
      requireName(secretId);
      if (!StudioVaultProvider.isValidSecretName(secretId)) {
        throw new UnknownReferenceException(secretId);
      }
      if (!secretUse.mayUse(principal, csiId, environment, secretId)) {
        // A name grants nothing (§9.2). The refusal names the reference and never the value.
        throw new SecretUseNotAuthorizedException(secretId);
      }
      if (!vault.listSecretNames(scope).contains(secretId))
        throw new UnknownReferenceException(secretId);
    }
  }

  @Override
  public Resolved resolve(
      String csiId,
      String environment,
      UUID testId,
      String principal,
      ReferenceDeclarations declarations) {
    return resolve(csiId,environment,testId,principal,declarations,id -> {});
  }

  @Override
  public Resolved resolve(String csiId,String environment,UUID testId,String principal,
      ReferenceDeclarations declarations,ValueReadEntry entryObserver) {
    refuseCrossedNames(declarations, true);
    VaultScope scope = VaultScope.of(csiId, environment, testId);

    Map<String, char[]> variables = new LinkedHashMap<>();
    Map<String, char[]> secrets = new LinkedHashMap<>();
    Map<String, String> versions = new LinkedHashMap<>();
    Map<String, List<String>> origins = new LinkedHashMap<>();
    Map<String, Decision> decisions = new LinkedHashMap<>();
    String currentSecret = null;
    var entered = new java.util.LinkedHashSet<String>();
    try {
      for (String name : declarations.variables()) {
        StudioVaultProvider.VaultEntry entry =
            vault
                .read(StudioVaultProvider.ReferenceKind.VARIABLE, scope, name)
                .orElseThrow(() -> new ReferenceUnavailableException(name));
        variables.put(name, entry.value());
      }
      for (String secretId : declarations.secrets()) {
        currentSecret = secretId;
        if (!StudioVaultProvider.isValidSecretName(secretId)) {
          throw new ReferenceUnavailableException(secretId);
        }
        // The recheck §5.1.3 asks for: entitlement is re-evaluated at dispatch, not inherited from
        // the acceptance that happened before an unbounded queue wait.
        if (!secretUse.mayUse(principal, csiId, environment, secretId)) {
          throw new SecretUseRevokedException(secretId);
        }
        entryObserver.beforeRead(secretId);
        entered.add(secretId);
        StudioVaultProvider.VaultEntry entry =
            vault
                .read(StudioVaultProvider.ReferenceKind.SECRET, scope, secretId)
                .orElseThrow(() -> new ReferenceUnavailableException(secretId));
        if (entry.value()==null || entry.versionIdentifier()==null || entry.versionIdentifier().isBlank() || entry.versionIdentifier().length()>256) {
          if(entry.value()!=null) Arrays.fill(entry.value(),'\0');throw new ReferenceUnavailableException(secretId);
        }
        if (entry.value().length == 0) { Arrays.fill(entry.value(),'\0');throw new ReferenceUnavailableException(secretId); }
        if (entry.value().length > 4096) {
          Arrays.fill(entry.value(), '\0');
          throw new SecretTooLongException(secretId);
        }
        secrets.put(secretId, entry.value());
        versions.put(secretId, entry.versionIdentifier());
        origins.put(secretId, entry.allowedOrigins());
        decisions.put(secretId, new Decision(DecisionOutcome.RESOLVED, entry.versionIdentifier()));
        currentSecret = null;
      }
      // A revocation during a bounded Vault read is rechecked before any release/frame is built.
      for(String secretId:declarations.secrets()) if(!secretUse.mayUse(principal,csiId,environment,secretId)) {
        decisions.put(secretId, new Decision(DecisionOutcome.REVOKED, versions.get(secretId)));
        throw new SecretUseRevokedException(secretId);
      }
    } catch (RuntimeException e) {
      if (currentSecret != null && (entered.contains(currentSecret)
          || e instanceof SecretUseRevokedException || e instanceof ReferenceUnavailableException)) {
        DecisionOutcome outcome = e instanceof VaultProviderUnavailableException ? DecisionOutcome.VAULT_UNAVAILABLE
            : e instanceof SecretUseRevokedException ? DecisionOutcome.REVOKED : DecisionOutcome.UNAVAILABLE;
        decisions.put(currentSecret, new Decision(outcome, versions.get(currentSecret)));
      }
      var positivelyNotEntered = new java.util.LinkedHashSet<>(declarations.secrets());
      positivelyNotEntered.removeAll(entered);
      positivelyNotEntered.removeAll(decisions.keySet());
      StudioReferenceResolver.attachDecisionFacts(e, decisions, positivelyNotEntered);
      // Everything read so far is erased before the exception leaves, on every refusal path.
      variables.values().forEach(value -> Arrays.fill(value, '\0'));
      secrets.values().forEach(value -> Arrays.fill(value, '\0'));
      throw e;
    }
    return new Resolved(variables, secrets, versions, origins);
  }

  public static final class SecretTooLongException extends RuntimeException {
    private static final long serialVersionUID = 1L;

    public SecretTooLongException(String id) {
      super("Secret exceeds the value bound: " + id);
    }
  }

  /** Names-only authorization recheck; no Vault read or list call. */
  public boolean mayUse(String principal, String csi, String environment, String secretId) {
    return secretUse.mayUse(principal, csi, environment, secretId);
  }

  /**
   * A name declared as both a variable and a secret is a refusal wherever it is found (AC-3).
   *
   * <p>At dispatch it would produce a job whose two resolved maps disagree about what the name
   * means, which is the crossed-type case the runner refuses at the envelope. Refusing it here as
   * well means the condition never depends on the far side noticing.
   */
  private static void refuseCrossedNames(ReferenceDeclarations declarations, boolean atDispatch) {
    for (String crossed : declarations.crossedNames()) {
      if (atDispatch) {
        throw new ReferenceUnavailableException(crossed);
      }
      throw new UnknownReferenceException(crossed);
    }
  }

  private static void requireName(String name) {
    if (name == null || name.isBlank()) {
      throw new UnknownReferenceException("");
    }
  }

  private static void erase(StudioVaultProvider.VaultEntry entry) {
    Arrays.fill(entry.value(), '\0');
  }

  /** Visible so a test can assert which provider a running context actually selected (AC-9). */
  public Optional<String> providerName() {
    return Optional.ofNullable(vault.name());
  }
}

package com.citi.put.checks.studio.validation;

import com.citi.put.checks.studio.dto.StudioVariable;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Checks a draft's variable references against its declared variables (Studio v1 WP6, plan ADD-7).
 *
 * <p>Source lines reference variables as {@code <var NAME>} and secrets as {@code <secret ID>}
 * (architecture §4.3). The token grammar here is the runner validator's, {@code
 * studio-runner/src/validator/references.ts}, so both sides agree on what a reference is. A {@code
 * secretRef} declaration is matched by its {@code secretId}, falling back to its name, exactly as
 * {@code CompileInputs} declares it to the compiler.
 *
 * <p>Three findings make a draft invalid:
 *
 * <ul>
 *   <li><b>undeclared</b> — a line references a name the draft does not declare with that kind;
 *   <li><b>unvalued</b> — a referenced plain variable has no value on the draft and none was
 *       supplied by the caller;
 *   <li><b>conflicting</b> — one name is declared both as a variable and as a secret.
 * </ul>
 *
 * <p>Declared-but-unreferenced names are reported as {@code unused} and do not invalidate. Secret
 * <em>values</em> are never checked or read here: whether a vault holds the id is decided at
 * dispatch, and a secret value never travels on this path (§9.2).
 */
public final class VariableReferenceValidator {

  private static final Pattern VARIABLE_TOKEN = Pattern.compile("<var\\s+([A-Za-z0-9_.-]{1,64})>");
  private static final Pattern SECRET_TOKEN = Pattern.compile("<secret\\s+([A-Za-z0-9_.-]{1,64})>");

  private VariableReferenceValidator() {}

  /**
   * The outcome. Names are listed in first-reference (or declaration) order.
   *
   * @param undeclared references with no matching declaration, as their source tokens
   * @param unvalued referenced plain variables with no value available
   * @param conflicting names declared both as a variable and as a secret
   * @param unused declared names no line references
   */
  public record Result(
      List<String> undeclared,
      List<String> unvalued,
      List<String> conflicting,
      List<String> unused) {

    public boolean isValid() {
      return undeclared.isEmpty() && unvalued.isEmpty() && conflicting.isEmpty();
    }

    /** Everything a run would lack, for a caller that shows one list. */
    public List<String> missing() {
      List<String> missing = new ArrayList<>(undeclared);
      missing.addAll(unvalued);
      return List.copyOf(missing);
    }
  }

  /**
   * @param steps the draft's source lines
   * @param declared the draft's declared variables
   * @param supplied values the caller supplies by name; may be empty, never read beyond presence
   */
  public static Result validate(
      List<String> steps, List<StudioVariable> declared, Map<String, ?> supplied) {
    Set<String> referencedVariables = new LinkedHashSet<>();
    Set<String> referencedSecrets = new LinkedHashSet<>();
    for (String step : steps == null ? List.<String>of() : steps) {
      if (step != null) {
        collect(VARIABLE_TOKEN, step, referencedVariables);
        collect(SECRET_TOKEN, step, referencedSecrets);
      }
    }

    Map<String, String> plainValues = new LinkedHashMap<>();
    Set<String> secretIds = new LinkedHashSet<>();
    for (StudioVariable variable : declared == null ? List.<StudioVariable>of() : declared) {
      if (variable == null) {
        continue;
      }
      if (StudioVariable.KIND_SECRET_REF.equals(variable.kind())) {
        String id = variable.secretId() == null ? variable.name() : variable.secretId();
        if (id != null) {
          secretIds.add(id);
        }
      } else if (variable.name() != null) {
        plainValues.put(variable.name(), variable.value());
      }
    }

    List<String> undeclared = new ArrayList<>();
    List<String> unvalued = new ArrayList<>();
    for (String name : referencedVariables) {
      if (!plainValues.containsKey(name)) {
        undeclared.add("<var " + name + ">");
      } else if (isBlank(plainValues.get(name)) && !isSupplied(supplied, name)) {
        unvalued.add(name);
      }
    }
    for (String id : referencedSecrets) {
      if (!secretIds.contains(id)) {
        undeclared.add("<secret " + id + ">");
      }
    }

    List<String> conflicting = new ArrayList<>();
    for (String name : plainValues.keySet()) {
      if (secretIds.contains(name)) {
        conflicting.add(name);
      }
    }

    List<String> unused = new ArrayList<>();
    for (String name : plainValues.keySet()) {
      if (!referencedVariables.contains(name)) {
        unused.add(name);
      }
    }
    for (String id : secretIds) {
      if (!referencedSecrets.contains(id)) {
        unused.add(id);
      }
    }

    return new Result(
        List.copyOf(undeclared),
        List.copyOf(unvalued),
        List.copyOf(conflicting),
        List.copyOf(unused));
  }

  /** The {@code <var NAME>} names one source line mentions, in first-mention order. */
  public static Set<String> variableTokens(String text) {
    Set<String> names = new LinkedHashSet<>();
    collect(VARIABLE_TOKEN, text, names);
    return names;
  }

  /** The {@code <secret ID>} ids one source line mentions, in first-mention order. */
  public static Set<String> secretTokens(String text) {
    Set<String> ids = new LinkedHashSet<>();
    collect(SECRET_TOKEN, text, ids);
    return ids;
  }

  private static void collect(Pattern pattern, String text, Set<String> into) {
    Matcher matcher = pattern.matcher(text);
    while (matcher.find()) {
      into.add(matcher.group(1));
    }
  }

  private static boolean isSupplied(Map<String, ?> supplied, String name) {
    if (supplied == null) {
      return false;
    }
    Object value = supplied.get(name);
    return value != null && !(value instanceof String text && text.isBlank());
  }

  private static boolean isBlank(String value) {
    return value == null || value.isBlank();
  }
}
