import com.fasterxml.jackson.databind.ObjectMapper;
import java.util.ArrayList;
import java.util.List;

/**
 * Reads the <b>typed</b> declared references off a confirmed revision (§8.3, §9.2, AC-1, AC-10).
 *
 * <p>The revision's {@code "references"} column holds declarations and never values, which is the
 * whole point of the column: names persist, values do not. This reader therefore cannot leak one,
 * because there is nothing in its input to leak — and it never puts its input in a message either,
 * which is AC-10's second constraint: a refusal names the <em>declaration</em> as unreadable and
 * never the revision's contents.
 *
 * <p><b>Fail-closed, and that is the change story 10.17 makes.</b> The previous reader walked any
 * shape it was given, collected whatever looked like a name, and returned an empty list for
 * anything it did not recognise. Combined with the dispatcher's {@code orElse(List.of())} that was
 * a silent fail-open: a dispatch whose revision could not be read proceeded as a run with no
 * references and no secrets, which for a login test is a browser opening a real application with an
 * empty password field. The epic's acceptance bullet is <em>"unauthorized or <b>missing</b>
 * reference prevents browser launch"</em>, so an unreadable, absent or unrecognised declaration is
 * now {@link UnreadableReferenceDeclarationException} and the dispatcher makes it terminal.
 *
 * <p>The recognised shape is exactly the one {@code CompileInputs.referencesJson()} writes and the
 * one the contract's {@code ReferenceDeclarations} declares: an object with {@code variables} and
 * {@code secrets}, each an array of strings, and no other key. Accepting more shapes than the
 * producer writes is how a reader stops being able to tell a corrupt document from an old one.
 */
public final class ExecutionReferences {

  private ExecutionReferences() {}

  /**
   * The typed declaration, in declaration order.
   *
   * @param mapper the JSON reader
   * @param referencesJson the revision's stored {@code references} document
   * @return the two sets, separately
   * @throws UnreadableReferenceDeclarationException when the document is absent, unparseable or of
   *     a shape this reader does not recognise
   */
  public static ReferenceDeclarations declared(ObjectMapper mapper, String referencesJson) {
    if (referencesJson == null || referencesJson.isBlank()) {
      throw new UnreadableReferenceDeclarationException(
          "the confirmed revision carries no reference declaration");
    }
    JsonNode node;
    try {
      node = mapper.readTree(referencesJson);
    } catch (com.fasterxml.jackson.core.JsonProcessingException e) {
      // The exception's message would quote the document. It is deliberately not chained here.
      throw new UnreadableReferenceDeclarationException(
          "the reference declaration on the confirmed revision is not readable JSON");
    }
    if (node == null || !node.isObject()) {
      throw new UnreadableReferenceDeclarationException(
          "the reference declaration on the confirmed revision is not an object");
    }
    for (String key : (Iterable<String>) node::fieldNames) {
      if (!"variables".equals(key) && !"secrets".equals(key)) {
        throw new UnreadableReferenceDeclarationException(
            "the reference declaration on the confirmed revision carries an unrecognised key");
      }
    }
    return new ReferenceDeclarations(
        names(node.get("variables"), "variables"), names(node.get("secrets"), "secrets"));
  }

  private static List<String> names(JsonNode array, String field) {
    if (array == null || !array.isArray()) {
      throw new UnreadableReferenceDeclarationException(
          "the reference declaration on the confirmed revision has no '" + field + "' array");
    }
    List<String> names = new ArrayList<>();
    for (JsonNode element : array) {
      if (!element.isTextual() || element.textValue().isBlank()) {
        throw new UnreadableReferenceDeclarationException(
            "the reference declaration's '" + field + "' array holds a non-name element");
      }
      names.add(element.textValue());
    }
    return names;
  }

  /**
   * An unreadable, absent or unrecognised declaration (AC-10).
   *
   * <p>Ruled {@code REFERENCE_UNAVAILABLE} by @po on 2026-09-11 on ADR-002 §15.3's axis — it is
   * <em>a fact about the draft and its environment</em>: the same principal attempting the same
   * draft fails identically and the remedy points at the author or at whoever restores the row.
   * Nothing about the principal's entitlement has changed, which is what would have made it {@code
   * AUTHORIZATION_REVOKED}. No ninth enum value, and the path stays dispatcher-side so {@code
   * x-assigned-by} stays true.
   *
   * <p>The message names the declaration. It never carries the document.
   */
  public static class UnreadableReferenceDeclarationException extends RuntimeException {

    private static final long serialVersionUID = 1L;

    public UnreadableReferenceDeclarationException(String message) {
      super(message);
    }
  }
}
package com.citi.put.checks.studio.dispatch;

import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

/**
 * The declared references of one confirmed revision, <b>typed</b> (§4.5, §8.3, contract {@code
 * ReferenceDeclarations}).
 *
 * <p>Story 10.8 already separates {@code plain} from {@code secretRef} when it writes {@code
 * {"variables": [...], "secrets": [...]}} onto the revision. Until story 10.17 that type was
 * destroyed one layer below, by a reader that flattened both arrays into a single {@code
 * List&lt;String&gt;} — so by the time anything downstream could act on a reference, nothing knew
 * which of them was a secret. A flat list cannot fill the contract's two resolved maps, cannot tell
 * a secret-use decision from a variable read, and cannot notice a secret id arriving among the
 * variables.
 *
 * <p>Order is declaration order and is preserved, because it is the order the author wrote and the
 * only order any assertion about "the second declared secret" could mean.
 *
 * @param variables declared {@code vars.get} names, in declaration order
 * @param secrets declared {@code vars.secret} ids, in declaration order
 */
public record ReferenceDeclarations(List<String> variables, List<String> secrets) {

  /** Nothing declared. Distinct from <em>unreadable</em>, which is terminal (AC-10). */
  public static final ReferenceDeclarations NONE = new ReferenceDeclarations(List.of(), List.of());

  public ReferenceDeclarations {
    variables = List.copyOf(variables);
    secrets = List.copyOf(secrets);
  }

  public boolean isEmpty() {
    return variables.isEmpty() && secrets.isEmpty();
  }

  /** A name declared as both a variable and a secret, which is a refusal wherever it is found. */
  public Set<String> crossedNames() {
    Set<String> crossed = new LinkedHashSet<>(variables);
    crossed.retainAll(Set.copyOf(secrets));
    return Set.copyOf(crossed);
  }
}
package com.citi.put.checks.studio.guided.bridge;

import static com.citi.put.checks.studio.guided.session.GuidedSessionException.require;

import com.citi.put.checks.studio.guided.session.GuidedContracts;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.UUID;

/** Trusted immutable provenance validation; deliberately performs no English extraction. */
public final class GuidedSourceReferenceValidator {
  public record ClassifiedRegion(int startUtf16, int endUtf16) {}

  public record Source(String text, List<ClassifiedRegion> approvedNonsecretRegions) {
    public Source {
      approvedNonsecretRegions = List.copyOf(approvedNonsecretRegions);
    }
  }

  public record ConfigurationValue(
      String value,
      String stepId,
      String kind,
      String intendedSlot,
      String scopeHash,
      boolean approvedNonsecret,
      String referenceName) {
    public ConfigurationValue(
        String value,
        String stepId,
        String kind,
        String intendedSlot,
        String scopeHash,
        boolean approvedNonsecret) {
      this(value, stepId, kind, intendedSlot, scopeHash, approvedNonsecret, null);
    }
  }

  public record Sources(
      String sourceRevision,
      String configurationRevision,
      Map<String, Source> steps,
      Map<String, ConfigurationValue> configuration) {
    public Sources {
      steps = Map.copyOf(steps);
      configuration = Map.copyOf(configuration);
    }
  }

  private final GuidedContracts contracts;

  public GuidedSourceReferenceValidator(GuidedContracts contracts) {
    this.contracts = contracts;
  }

  public ObjectNode resolve(JsonNode session, Sources sources, JsonNode candidate) {
    contracts.validate("v3/source-reference", candidate);
    JsonNode scope = session.path("scope");
    require(
        sources.sourceRevision().equals(scope.path("sourceRevision").asText())
            && sources.configurationRevision().equals(scope.path("configurationRevision").asText()),
        "REVISION_CONFLICT",
        409);
    String step = candidate.path("stepId").asText(), kind = candidate.path("kind").asText();
    String slot = candidate.path("intendedSlot").asText();
    boolean stepExists = false;
    for (JsonNode sourceStep : session.path("sourceSteps")) {
      stepExists |= sourceStep.path("stepId").asText().equals(step);
    }
    require(
        stepExists && (kind.equals("destination") == slot.equals("navigate.destination")),
        "INVALID_CONTRACT",
        422);
    String value;
    if (candidate.path("referenceKind").asText().equals("sourceSpan")) {
      require(
          candidate.path("sourceRevision").asText().equals(sources.sourceRevision()),
          "REVISION_CONFLICT",
          409);
      Source source = sources.steps().get(step);
      require(source != null, "FORBIDDEN_SCOPE", 403);
      int start = candidate.path("startUtf16").asInt(), end = candidate.path("endUtf16").asInt();
      require(
          start < end
              && end <= source.text().length()
              && boundary(source.text(), start)
              && boundary(source.text(), end),
          "INVALID_CONTRACT",
          422);
      require(
          source.approvedNonsecretRegions().stream()
              .anyMatch(region -> region.startUtf16() <= start && region.endUtf16() >= end),
          "FORBIDDEN_SCOPE",
          403);
      value = source.text().substring(start, end);
    } else {
      require(
          candidate.path("configurationRevision").asText().equals(sources.configurationRevision()),
          "REVISION_CONFLICT",
          409);
      ConfigurationValue config =
          sources.configuration().get(candidate.path("referenceId").asText());
      require(
          config != null
              && (config.approvedNonsecret() || kind.equals("secretRef"))
              && config.stepId().equals(step)
              && config.kind().equals(kind)
              && config.intendedSlot().equals(slot)
              && config.scopeHash().equals(session.path("scopeHash").asText()),
          "FORBIDDEN_SCOPE",
          403);
      if (kind.equals("secretRef")) {
        require(
            slot.equals("fill.value")
                && candidate.path("referenceName").asText().equals(config.referenceName())
                && com.citi.put.checks.studio.secrets.StudioVaultProvider.isValidSecretName(
                    config.referenceName()),
            "FORBIDDEN_SCOPE",
            403);
        ObjectNode input =
            contracts
                .object()
                .put("inputId", UUID.randomUUID().toString())
                .put("sourceStepId", step)
                .put("kind", "secretRef")
                .put("secretId", config.referenceName())
                .put("intendedSlot", "fill.value");
        input.set("provenance", candidate.deepCopy());
        return input;
      }
      value = config.value();
    }
    require(value.getBytes(StandardCharsets.UTF_8).length <= 4096, "INVALID_CONTRACT", 422);
    // canonical validates complete UTF-16, without normalizing or decoding source bytes.
    GuidedContracts.canonical(contracts.object().put("value", value));
    if (kind.equals("destination")) {
      String origin = origin(value);
      boolean allowed = false;
      for (JsonNode approved : scope.path("approvedOrigins")) {
        allowed |= approved.asText().equals(origin);
      }
      require(allowed && value.length() <= 2048, "ORIGIN_NOT_ALLOWED", 403);
    }
    ObjectNode input =
        contracts
            .object()
            .put("inputId", UUID.randomUUID().toString())
            .put("sourceStepId", step)
            .put("kind", kind)
            .put("value", value)
            .put("intendedSlot", slot);
    input.set("provenance", candidate.deepCopy());
    return input;
  }

  private static boolean boundary(String text, int offset) {
    return offset == 0
        || offset == text.length()
        || !(Character.isHighSurrogate(text.charAt(offset - 1))
            && Character.isLowSurrogate(text.charAt(offset)));
  }

  public static String origin(String value) {
    try {
      URI uri = URI.create(value);
      require(
          Set.of("http", "https").contains(uri.getScheme())
              && uri.getHost() != null
              && uri.getRawUserInfo() == null,
          "ORIGIN_NOT_ALLOWED",
          403);
      int port = uri.getPort();
      return uri.getScheme()
          + "://"
          + uri.getHost().toLowerCase(java.util.Locale.ROOT)
          + (port == -1
                  || port == 80 && uri.getScheme().equals("http")
                  || port == 443 && uri.getScheme().equals("https")
              ? ""
              : ":" + port);
    } catch (IllegalArgumentException failure) {
      throw new com.citi.put.checks.studio.guided.session.GuidedSessionException(
          "ORIGIN_NOT_ALLOWED", 403);
    }
  }
}

