   143	        if (entry.value().length == 0) { Arrays.fill(entry.value(),'\0');throw new ReferenceUnavailableException(secretId); }
   144	        if (entry.value().length > 4096) {
   145	          Arrays.fill(entry.value(), '\0');
   146	          throw new SecretTooLongException(secretId);
   147	        }
   148	        secrets.put(secretId, entry.value());
   149	        versions.put(secretId, entry.versionIdentifier());
   150	        origins.put(secretId, entry.allowedOrigins());
   151	        decisions.put(secretId, new Decision(DecisionOutcome.RESOLVED, entry.versionIdentifier()));
   152	        currentSecret = null;
   153	      }
   154	      // A revocation during a bounded Vault read is rechecked before any release/frame is built.
   155	      for(String secretId:declarations.secrets()) if(!secretUse.mayUse(principal,csiId,environment,secretId)) {
   156	        decisions.put(secretId, new Decision(DecisionOutcome.REVOKED, versions.get(secretId)));
   157	        throw new SecretUseRevokedException(secretId);
   158	      }
   159	    } catch (RuntimeException e) {
   160	      if (currentSecret != null && (entered.contains(currentSecret)
   161	          || e instanceof SecretUseRevokedException || e instanceof ReferenceUnavailableException)) {
   162	        DecisionOutcome outcome = e instanceof VaultProviderUnavailableException ? DecisionOutcome.VAULT_UNAVAILABLE
   163	            : e instanceof SecretUseRevokedException ? DecisionOutcome.REVOKED : DecisionOutcome.UNAVAILABLE;
   164	        decisions.put(currentSecret, new Decision(outcome, versions.get(currentSecret)));
   165	      }
   166	      var positivelyNotEntered = new java.util.LinkedHashSet<>(declarations.secrets());
   167	      positivelyNotEntered.removeAll(entered);
   168	      positivelyNotEntered.removeAll(decisions.keySet());
   169	      StudioReferenceResolver.attachDecisionFacts(e, decisions, positivelyNotEntered);
   170	      // Everything read so far is erased before the exception leaves, on every refusal path.
   171	      variables.values().forEach(value -> Arrays.fill(value, '\0'));
   172	      secrets.values().forEach(value -> Arrays.fill(value, '\0'));
   173	      throw e;
   174	    }
   175	    return new Resolved(variables, secrets, versions, origins);
   176	  }
   177	
   178	  public static final class SecretTooLongException extends RuntimeException {
   179	    private static final long serialVersionUID = 1L;
   180	
   181	    public SecretTooLongException(String id) {
   182	      super("Secret exceeds the value bound: " + id);
   183	    }
   184	  }
   185	
   186	  /** Names-only authorization recheck; no Vault read or list call. */
   187	  public boolean mayUse(String principal, String csi, String environment, String secretId) {
   188	    return secretUse.mayUse(principal, csi, environment, secretId);
   189	  }
   190	
   191	  /**
   192	   * A name declared as both a variable and a secret is a refusal wherever it is found (AC-3).
   193	   *
   194	   * <p>At dispatch it would produce a job whose two resolved maps disagree about what the name
   195	   * means, which is the crossed-type case the runner refuses at the envelope. Refusing it here as
   196	   * well means the condition never depends on the far side noticing.
   197	   */
   198	  private static void refuseCrossedNames(ReferenceDeclarations declarations, boolean atDispatch) {
   199	    for (String crossed : declarations.crossedNames()) {
   200	      if (atDispatch) {
   201	        throw new ReferenceUnavailableException(crossed);
   202	      }
   203	      throw new UnknownReferenceException(crossed);
   204	    }
   205	  }
   206	
   207	  private static void requireName(String name) {
   208	    if (name == null || name.isBlank()) {
   209	      throw new UnknownReferenceException("");
   210	    }
   211	  }
   212	
   213	  private static void erase(StudioVaultProvider.VaultEntry entry) {
   214	    Arrays.fill(entry.value(), '\0');
   215	  }
   216	
   217	  /** Visible so a test can assert which provider a running context actually selected (AC-9). */
   218	  public Optional<String> providerName() {
   219	    return Optional.ofNullable(vault.name());
   220	  }
