package com.citi.put.checks.studio.secrets;

import com.fasterxml.jackson.core.JsonEncoding;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.net.URI;
import java.net.URLEncoder;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Optional;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.FutureTask;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;
import java.util.function.Consumer;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Minimal HashiCorp Vault KV v2 adapter: a bounded read, a create-only write and a metadata list.
 *
 * <p>Every call is test-scoped: the path template renders {@code {csiId}}, {@code {environment}},
 * {@code {testId}}, {@code {kind}} and {@code {referenceName}} from a {@link VaultScope}, and the
 * list prefix is that same template minus its last segment ({@link
 * StudioVaultConfiguration#listPrefixTemplate}), so save, list and read cannot address different
 * places.
 *
 * <p>Every call shares one bounded transport: the connect and request timeouts, the response-size
 * cap, no redirects, and the token read from the mounted file on each call.
 *
 * <p><b>The write body, and its residual.</b> The value is written as {@code char[]} straight into
 * a buffer this class owns, sent from that buffer without a copy, and the buffer is zero-filled on
 * every exit path. What is not claimed: Jackson's recycled generator buffers and the HTTP client's
 * transient buffers can still hold bytes of the body until they are reused. The same stance as
 * {@code StudioReferenceResolver.Resolved} (AC-15).
 *
 * <p>Nothing here logs a value, a response body, or a URI that could carry one. A name may be
 * logged.
 */
public final class HashicorpStudioVaultProvider implements StudioVaultProvider {

  public static final String NAME = "hashicorp";

  private static final Logger LOGGER = LoggerFactory.getLogger(HashicorpStudioVaultProvider.class);

  private final StudioSecretsProperties.Vault.Hashicorp properties;
  private final ObjectMapper objectMapper;
  private final HttpClient client;

  /**
   * Handed each write buffer's backing array when the buffer is created, so a test can prove the
   * array is zero after {@link #create} returns or throws. {@code null} outside tests.
   */
  private Consumer<byte[]> writeBufferObserver;

  public HashicorpStudioVaultProvider(
      StudioSecretsProperties.Vault.Hashicorp properties, ObjectMapper objectMapper) {
    this.properties = properties;
    this.objectMapper = objectMapper;
    this.client =
        HttpClient.newBuilder()
            .connectTimeout(properties.connectTimeoutOrDefault())
            .followRedirects(HttpClient.Redirect.NEVER)
            .build();
  }

  @Override
  public String name() {
    return NAME;
  }

  @Override
  public Optional<VaultEntry> read(ReferenceKind kind, VaultScope scope, String referenceName) {
    long deadline = System.nanoTime() + properties.requestTimeoutOrDefault().toNanos();
    try {
      HttpResponse<InputStream> response =
          client.send(
              request(dataUri(kind, scope, referenceName)).GET().build(),
              HttpResponse.BodyHandlers.ofInputStream());
      try (InputStream body = response.body()) {
        if (response.statusCode() == 404) {
          return Optional.empty();
        }
        if (!isSuccess(response.statusCode())) {
          throw new VaultProviderUnavailableException(
              "Vault refused the reference read with status " + response.statusCode());
        }
        byte[] bytes = readBody(body, deadline);
        VaultEntry entry;
        try {
          entry = parse(bytes);
        } finally {
          Arrays.fill(bytes, (byte) 0);
        }
        if (kind == ReferenceKind.SECRET && entry.allowedOrigins().isEmpty()) {
          // Names the reference only. Origins are not secret, but the list is not echoed either:
          // the entry's owner can read it, and a log line is not where it should be corrected.
          LOGGER.warn(
              "Vault entry for secret '{}' declares no valid {}; it cannot be filled on any origin",
              referenceName,
              SecretOrigins.VAULT_KEY);
        }
        return Optional.of(entry);
      }
    } catch (VaultProviderUnavailableException e) {
      throw e;
    } catch (InterruptedException e) {
      Thread.currentThread().interrupt();
      throw new VaultProviderUnavailableException("Vault reference read was interrupted", e);
    } catch (IOException | RuntimeException e) {
      throw new VaultProviderUnavailableException("Vault reference read failed", e);
    }
  }

  /**
   * Create-only write: {@code POST {mount}/data/{path}} with {@code options.cas = 0}, so Vault
   * refuses to overwrite an existing entry.
   *
   * <p>A refused write ({@code 400}, or {@code 403} under a policy that grants {@code create} but
   * not {@code update}) is told apart from an outage by reading the entry's metadata: metadata
   * present means the name is taken ({@link SecretAlreadyExistsException}); anything else is {@link
   * VaultProviderUnavailableException}. That the platform Vault answers a duplicate under a
   * create-only policy with {@code 403} is an inference from HashiCorp's documentation, not a
   * verified behaviour.
   *
   * <p>{@code value} belongs to the caller, who erases it. The serialized body is erased here.
   */
  @Override
  public String create(VaultScope scope, String name, char[] value, List<String> origins) {
    long deadline = System.nanoTime() + properties.requestTimeoutOrDefault().toNanos();
    ErasableBuffer buffer = new ErasableBuffer(initialCapacity(value, origins));
    if (writeBufferObserver != null) {
      writeBufferObserver.accept(buffer.backingArray());
    }
    try {
      writeCreateBody(buffer, value, origins);
      HttpResponse<InputStream> response =
          client.send(
              request(dataUri(ReferenceKind.SECRET, scope, name))
                  .header("Content-Type", "application/json")
                  .POST(buffer.publisher())
                  .build(),
              HttpResponse.BodyHandlers.ofInputStream());
      try (InputStream body = response.body()) {
        int status = response.statusCode();
        if (isSuccess(status)) {
          return writtenVersion(readBody(body, deadline));
        }
        if (status == 400 || status == 403) {
          if (metadataExists(scope, name, deadline)) {
            throw new SecretAlreadyExistsException(name);
          }
        }
        throw new VaultProviderUnavailableException(
            "Vault refused the secret write with status " + status);
      }
    } catch (VaultProviderUnavailableException | SecretAlreadyExistsException e) {
      throw e;
    } catch (InterruptedException e) {
      Thread.currentThread().interrupt();
      throw new VaultProviderUnavailableException("Vault secret write was interrupted", e);
    } catch (IOException | RuntimeException e) {
      throw new VaultProviderUnavailableException("Vault secret write failed", e);
    } finally {
      buffer.erase();
    }
  }

  /**
   * {@code LIST {mount}/metadata/{prefix}} (sent as {@code GET ?list=true}, the documented
   * equivalent). A {@code 404} is an empty folder. Sub-folders and keys that fail {@link
   * StudioVaultProvider#isValidSecretName} are skipped: no step could reference them.
   */
  @Override
  public List<String> listSecretNames(VaultScope scope) {
    long deadline = System.nanoTime() + properties.requestTimeoutOrDefault().toNanos();
    try {
      HttpResponse<InputStream> response =
          client.send(
              request(listUri(scope)).GET().build(), HttpResponse.BodyHandlers.ofInputStream());
      try (InputStream body = response.body()) {
        if (response.statusCode() == 404) {
          return List.of();
        }
        if (!isSuccess(response.statusCode())) {
          throw new VaultProviderUnavailableException(
              "Vault refused the secret list with status " + response.statusCode());
        }
        JsonNode keys = objectMapper.readTree(readBody(body, deadline)).path("data").path("keys");
        if (!keys.isArray()) {
          throw new VaultProviderUnavailableException("Vault returned a malformed KV v2 list");
        }
        List<String> names = new ArrayList<>();
        for (JsonNode key : keys) {
          String candidate = key.isTextual() ? key.textValue() : null;
          if (candidate != null
              && !candidate.endsWith("/")
              && StudioVaultProvider.isValidSecretName(candidate)) {
            names.add(candidate);
          }
        }
        names.sort(null);
        return List.copyOf(names);
      }
    } catch (VaultProviderUnavailableException e) {
      throw e;
    } catch (InterruptedException e) {
      Thread.currentThread().interrupt();
      throw new VaultProviderUnavailableException("Vault secret list was interrupted", e);
    } catch (IOException | RuntimeException e) {
      throw new VaultProviderUnavailableException("Vault secret list failed", e);
    }
  }

  /** Whether the entry's metadata exists: the one question a refused create-only write asks. */
  private boolean metadataExists(VaultScope scope, String name, long deadline)
      throws IOException, InterruptedException {
    HttpResponse<InputStream> response =
        client.send(
            request(metadataUri(scope, name)).GET().build(),
            HttpResponse.BodyHandlers.ofInputStream());
    try (InputStream body = response.body()) {
      if (response.statusCode() != 200) {
        return false;
      }
      readBody(body, deadline);
      return true;
    }
  }

  private void writeCreateBody(ErasableBuffer buffer, char[] value, List<String> origins)
      throws IOException {
    try (JsonGenerator generator =
        objectMapper.getFactory().createGenerator(buffer, JsonEncoding.UTF8)) {
      generator.writeStartObject();
      generator.writeObjectFieldStart("options");
      generator.writeNumberField("cas", 0);
      generator.writeEndObject();
      generator.writeObjectFieldStart("data");
      generator.writeFieldName(properties.valueKeyOrDefault());
      generator.writeString(value, 0, value.length);
      generator.writeStringField(SecretOrigins.VAULT_KEY, String.join(",", origins));
      generator.writeEndObject();
      generator.writeEndObject();
    }
  }

  /**
   * Sized so the buffer never grows: a JSON-escaped character is at most six bytes, and every
   * origin, the value key and the envelope are counted.
   */
  private int initialCapacity(char[] value, List<String> origins) {
    long capacity = 256L + 6L * value.length + 6L * properties.valueKeyOrDefault().length();
    for (String origin : origins) {
      capacity += 6L * (origin.length() + 1);
    }
    return (int) Math.min(capacity, Integer.MAX_VALUE - 8);
  }

  private String writtenVersion(byte[] body) throws IOException {
    JsonNode version = objectMapper.readTree(body).path("data").path("version");
    if (!version.canConvertToInt() || version.asInt() <= 0) {
      throw new VaultProviderUnavailableException(
          "Vault returned a malformed KV v2 write response");
    }
    return Integer.toString(version.asInt());
  }

  private byte[] readBody(InputStream body, long deadline)
      throws IOException, InterruptedException {
    byte[] bytes = readBounded(body, properties.maxResponseBytesOrDefault() + 1, deadline);
    if (bytes.length > properties.maxResponseBytesOrDefault()) {
      throw new VaultProviderUnavailableException("Vault returned an oversized response");
    }
    return bytes;
  }

  private HttpRequest.Builder request(URI uri) throws IOException {
    HttpRequest.Builder request =
        HttpRequest.newBuilder(uri)
            .timeout(properties.requestTimeoutOrDefault())
            .header("Accept", "application/json")
            .header("X-Vault-Request", "true")
            .header("X-Vault-Token", readToken());
    if (properties.namespace() != null && !properties.namespace().isBlank()) {
      request.header("X-Vault-Namespace", properties.namespace().trim());
    }
    return request;
  }

  private static boolean isSuccess(int status) {
    return status >= 200 && status < 300;
  }

  private static byte[] readBounded(InputStream body, int limit, long deadline)
      throws IOException, InterruptedException {
    FutureTask<byte[]> read =
        new FutureTask<>(
            () -> {
              try {
                return body.readNBytes(limit);
              } catch (IOException e) {
                throw new VaultBodyReadException(e);
              }
            });
    Thread reader = Thread.ofVirtual().name("studio-vault-body-reader").start(read);
    long remaining = deadline - System.nanoTime();
    if (remaining <= 0) {
      read.cancel(true);
      body.close();
      throw new VaultProviderUnavailableException("Vault response exceeded the request deadline");
    }
    try {
      return read.get(remaining, TimeUnit.NANOSECONDS);
    } catch (TimeoutException e) {
      read.cancel(true);
      body.close();
      throw new VaultProviderUnavailableException(
          "Vault response exceeded the request deadline", e);
    } catch (ExecutionException e) {
      if (e.getCause() instanceof VaultBodyReadException bodyRead) {
        throw bodyRead.ioCause();
      }
      throw new VaultProviderUnavailableException("Vault response could not be read", e);
    } finally {
      if (!read.isDone()) {
        reader.interrupt();
      }
    }
  }

  private static final class VaultBodyReadException extends RuntimeException {
    private static final long serialVersionUID = 1L;

    private VaultBodyReadException(IOException cause) {
      super(cause);
    }

    private IOException ioCause() {
      return (IOException) getCause();
    }
  }

  private VaultEntry parse(byte[] body) throws IOException {
    char[] value = null;
    int version = 0;
    List<String> origins = List.of();
    var path = new java.util.ArrayDeque<String>();
    try (var parser = objectMapper.getFactory().createParser(body)) {
      com.fasterxml.jackson.core.JsonToken token;
      String field = null;
      while ((token = parser.nextToken()) != null) {
        if (token == com.fasterxml.jackson.core.JsonToken.FIELD_NAME) {
          field = parser.currentName();
        } else if (token == com.fasterxml.jackson.core.JsonToken.START_OBJECT
            || token == com.fasterxml.jackson.core.JsonToken.START_ARRAY) {
          path.addLast(field == null ? "$" : field);
          field = null;
        } else if (token.isStructEnd()) {
          path.removeLast();
          field = null;
        } else if (List.copyOf(path).equals(List.of("$", "data", "data"))) {
          if (properties.valueKeyOrDefault().equals(field)) {
            if (token != com.fasterxml.jackson.core.JsonToken.VALUE_STRING || value != null) {
              throw new VaultProviderUnavailableException(
                  "Vault returned a malformed KV v2 response");
            }
            value =
                java.util.Arrays.copyOfRange(
                    parser.getTextCharacters(),
                    parser.getTextOffset(),
                    parser.getTextOffset() + parser.getTextLength());
          } else if (SecretOrigins.VAULT_KEY.equals(field)
              && token == com.fasterxml.jackson.core.JsonToken.VALUE_STRING) {
            origins = SecretOrigins.parse(parser.getText());
          }
        } else if (List.copyOf(path).equals(List.of("$", "data", "metadata"))
            && "version".equals(field)
            && token == com.fasterxml.jackson.core.JsonToken.VALUE_NUMBER_INT) {
          version = parser.getIntValue();
        }
      }
      if (value == null || version <= 0)
        throw new VaultProviderUnavailableException("Vault returned a malformed KV v2 response");
      return new VaultEntry(value, Integer.toString(version), origins);
    } catch (IOException | RuntimeException failure) {
      if (value != null) java.util.Arrays.fill(value, '\0');
      throw failure;
    }
  }

  /**
   * The entry's {@value SecretOrigins#VAULT_KEY}, normalized. Absent, non-text or malformed all
   * mean no origin: the secret then cannot be filled, which is the fail-closed reading. Nothing
   * about a malformed list is thrown or logged here, because nothing here knows which reference it
   * was; {@link #read} says so by name.
   */
  private static List<String> allowedOrigins(JsonNode node) {
    return node.isTextual() ? SecretOrigins.parse(node.textValue()) : List.of();
  }

  private URI dataUri(ReferenceKind kind, VaultScope scope, String referenceName) {
    return vaultUri("data", render(properties.pathTemplateOrDefault(), kind, scope, referenceName));
  }

  private URI metadataUri(VaultScope scope, String name) {
    return vaultUri(
        "metadata", render(properties.pathTemplateOrDefault(), ReferenceKind.SECRET, scope, name));
  }

  private URI listUri(VaultScope scope) {
    String prefix = StudioVaultConfiguration.listPrefixTemplate(properties.pathTemplateOrDefault());
    return URI.create(
        vaultUri("metadata", render(prefix, ReferenceKind.SECRET, scope, null)) + "?list=true");
  }

  private static String render(
      String template, ReferenceKind kind, VaultScope scope, String referenceName) {
    String path =
        template
            .replace("{csiId}", segment(scope.csiId()))
            .replace("{environment}", segment(scope.environment()))
            .replace("{testId}", segment(scope.testId()))
            .replace("{kind}", kind == ReferenceKind.SECRET ? "secrets" : "variables");
    return referenceName == null ? path : path.replace("{referenceName}", segment(referenceName));
  }

  private URI vaultUri(String api, String path) {
    String base = properties.address().replaceAll("/+$", "");
    return URI.create(
        base + "/v1/" + segment(properties.mountOrDefault()) + "/" + api + "/" + path);
  }

  private String readToken() throws IOException {
    String token = Files.readString(Path.of(properties.tokenFile())).trim();
    if (token.isEmpty()) {
      throw new IOException("empty Vault token file");
    }
    return token;
  }

  private static String segment(String value) {
    if (value == null || value.isBlank()) {
      throw new VaultProviderUnavailableException("Vault reference coordinates are incomplete");
    }
    if (value.contains("/") || value.contains("\\") || ".".equals(value) || "..".equals(value)) {
      throw new VaultProviderUnavailableException("Vault reference coordinates are not path-safe");
    }
    return URLEncoder.encode(value, StandardCharsets.UTF_8).replace("+", "%20");
  }

  /** Test hook: see {@link #writeBufferObserver}. */
  void observeWriteBuffers(Consumer<byte[]> observer) {
    this.writeBufferObserver = observer;
  }

  /**
   * A body buffer that can be erased. It exposes its backing array to the request publisher rather
   * than copying it out, and when it must grow it zero-fills the array it leaves behind, so at no
   * point does an unerased copy of the body exist that this class cannot reach.
   */
  private static final class ErasableBuffer extends ByteArrayOutputStream {

    private ErasableBuffer(int capacity) {
      super(capacity);
    }

    @Override
    public synchronized void write(int b) {
      ensureErasingCapacity(1);
      super.write(b);
    }

    @Override
    public synchronized void write(byte[] bytes, int offset, int length) {
      ensureErasingCapacity(length);
      super.write(bytes, offset, length);
    }

    private void ensureErasingCapacity(int extra) {
      if (count + extra <= buf.length) {
        return;
      }
      byte[] grown = Arrays.copyOf(buf, Math.max(buf.length * 2, count + extra));
      Arrays.fill(buf, (byte) 0);
      buf = grown;
    }

    private synchronized byte[] backingArray() {
      return buf;
    }

    private synchronized HttpRequest.BodyPublisher publisher() {
      return HttpRequest.BodyPublishers.ofByteArray(buf, 0, count);
    }

    private synchronized void erase() {
      Arrays.fill(buf, (byte) 0);
      count = 0;
    }
  }
}

package com.citi.put.checks.studio.secrets;

import com.citi.put.checks.studio.internal.InternalCallbackCodes;
import com.citi.put.checks.studio.internal.InternalCallbackException;
import com.citi.put.checks.studio.internal.dto.RunnerReport;
import com.citi.put.checks.studio.internal.dto.RunnerStepState;
import com.fasterxml.jackson.databind.JsonNode;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

/** Raw completed receipts and frozen recipes establish use before projection can round or merge. */
public final class ObservedProgressSecretEvidence {
  private ObservedProgressSecretEvidence() {}

  public static void require(RunnerReport report, JsonNode artifact) {
    if (!RunnerReport.PROGRESS.equals(report.kind()) || report.secretUse().isEmpty()) return;
    if (report.browserStartedAt()==null || report.outcome()!=null || report.evidence()!=null
        || report.secretUse().values().stream().anyMatch(value->!"USED".equals(value))) throw invalid();
    JsonNode steps=artifact.path("steps"), recipes=artifact.path("inputRecipes");
    if (!steps.isArray() || !recipes.isArray() || report.steps()==null) throw invalid();
    Map<String,JsonNode> byInput=new HashMap<>();
    for (JsonNode recipe:recipes) {
      String id=recipe.path("inputId").asText();
      if(id.isEmpty() || byInput.putIfAbsent(id,recipe)!=null)throw invalid();
    }
    int prior=-1;Set<String> proven=new HashSet<>();
    for(RunnerStepState receipt:report.steps()) {
      if(receipt==null || receipt.stepIndex()==null || receipt.stepIndex()<=prior || receipt.stepIndex()<0 || receipt.stepIndex()>=steps.size())throw invalid();
      prior=receipt.stepIndex();
      if (!"PASS".equals(receipt.status()))continue;
      if(receipt.failure()!=null || !reading(receipt.startedAtMs()) || !reading(receipt.finishedAtMs()) || !reading(receipt.durationMs())
          || receipt.finishedAtMs()<receipt.startedAtMs()
          || Math.abs(receipt.durationMs()-(receipt.finishedAtMs()-receipt.startedAtMs()))>=0.001)throw invalid();
      JsonNode frozen=steps.get(receipt.stepIndex());
      if(frozen.path("stepIndex").asInt(-1)!=receipt.stepIndex() || frozen.path("stepId").asText().isEmpty() || !frozen.path("operations").isArray())throw invalid();
      for(JsonNode action:frozen.path("operations")) {
        JsonNode operation=action.path("operation"),value=operation.path("value");
        if(!operation.path("kind").asText().equals("fill") || !value.path("kind").asText().equals("secretRef"))continue;
        JsonNode recipe=byInput.get(value.path("sourceInputId").asText());
        if(recipe==null || !recipe.path("kind").asText().equals("secretRef")
            || !recipe.path("stepId").equals(frozen.path("stepId"))
            || !action.path("coordinate").path("stepId").equals(frozen.path("stepId"))
            || !recipe.path("intendedSlot").asText().equals("fill.value")
            || !recipe.path("provenance").path("kind").asText().equals("configuration"))throw invalid();
        String name=recipe.path("provenance").path("referenceName").asText();
        if(!StudioVaultProvider.isValidSecretName(name))throw invalid();
        proven.add(name);
      }
    }
    if(!proven.containsAll(report.secretUse().keySet()))throw invalid();
  }

  private static boolean reading(Double value) { return value!=null && Double.isFinite(value) && value>=0; }
  private static InternalCallbackException invalid() {
    return InternalCallbackException.badRequest(InternalCallbackCodes.INVALID_REPORT,"Invalid completed secret-use evidence");
  }
}
package com.citi.put.checks.studio.internal;

import com.citi.put.checks.studio.StudioExecutionProperties;
import com.citi.put.checks.studio.StudioService;
import com.citi.put.checks.studio.UITestExecutionRepository;
import com.citi.put.checks.studio.dispatch.DispatchState;
import com.citi.put.checks.studio.dispatch.StudioDispatchLedgerStatements;
import com.citi.put.checks.studio.dto.ExecutionLogEntry;
import com.citi.put.checks.studio.dto.ExecutionStatus;
import com.citi.put.checks.studio.dto.StepResult;
import com.citi.put.checks.studio.dto.VideoEvidence;
import com.citi.put.checks.studio.entity.UITestExecution;
import com.citi.put.checks.studio.entity.UITestRevision;
import com.citi.put.checks.studio.guided.session.GuidedContracts;
import com.citi.put.checks.studio.internal.dto.ProgressAck;
import com.citi.put.checks.studio.internal.dto.RunnerReport;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.persistence.EntityManager;
import jakarta.persistence.PersistenceContext;
import java.time.Clock;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.UUID;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.support.TransactionSynchronization;
import org.springframework.transaction.support.TransactionSynchronizationManager;

/**
 * Applies a runner report, or refuses it (AC-20 – AC-27).
 *
 * <p><b>Acknowledge only after commit.</b> This method is the transaction; the controller writes
 * the response after it returns. Because the runner retries a terminal report byte-identically
 * until it is acknowledged (10.6 AC-17) and holds no durable store to replay from, an
 * acknowledgement sent before the commit loses a terminal result on a crash. The ordering is the
 * criterion, not a note.
 *
 * <p><b>One conditional statement per report.</b> Ownership, sequence and the permitted transition
 * all sit in the {@code WHERE} of the statement that applies the change; zero rows is a {@code 409}
 * and never a silent {@code 200}.
 *
 * <p><b>The one asymmetry that matters.</b> A duplicate delivery of an already-applied {@code
 * (attemptId, runnerSequence)} from the <em>exactly matching</em> identity is {@code 200} applying
 * nothing. A <em>differing</em> identity is {@code 409}. The rule is symmetric across both internal
 * routes and is named that way here on purpose: a byte-identical re-delivery is the same owner
 * obeying the retry-until-acknowledged rule this API imposed, and answering {@code 409} would write
 * a false ownership-loss line for a runner that did exactly as instructed.
 */
@Service
public class ProgressReportService {

  private static final GuidedContracts OBSERVED_CONTRACTS = new GuidedContracts();

  private static final Logger LOGGER = LoggerFactory.getLogger(ProgressReportService.class);

  private static final TypeReference<List<StepResult>> STEP_RESULTS = new TypeReference<>() {};

  private final StudioDispatchLedgerStatements statements;
  private final UITestExecutionRepository executions;
  private final StudioService studioService;
  private final StudioExecutionProperties properties;
  private final ObjectMapper objectMapper;
  private final List<ReportCommitHook> commitHooks;
  private final Clock clock;
  private com.citi.put.checks.studio.secrets.SecretAuditLifecycle secretAudit;

  @Autowired(required = false)
  public void installSecretAudit(com.citi.put.checks.studio.secrets.SecretAuditLifecycle audit) {
    this.secretAudit = audit;
  }

  private com.citi.put.checks.studio.secrets.SecretRevocationSweep secretRevocation;

  @Autowired(required = false)
  public void installSecretRevocation(
      com.citi.put.checks.studio.secrets.SecretRevocationSweep sweep) {
    this.secretRevocation = sweep;
  }

  /**
   * The report is applied by SQL statements, not by JPA. Anything this transaction has already
   * loaded through JPA — the history row read for the revision's ordered source — is therefore
   * stale the moment a statement lands, and Hibernate's first-level cache would hand that stale
   * copy back to the acknowledgement and to the last-run projection. Clearing the session after a
   * successful application is what makes both read the row the database actually holds.
   */
  @PersistenceContext private EntityManager entityManager;

  @Autowired
  public ProgressReportService(
      StudioDispatchLedgerStatements statements,
      UITestExecutionRepository executions,
      StudioService studioService,
      StudioExecutionProperties properties,
      ObjectMapper objectMapper,
      List<ReportCommitHook> commitHooks) {
    this(
        statements,
        executions,
        studioService,
        properties,
        objectMapper,
        commitHooks,
        Clock.systemUTC());
  }

  ProgressReportService(
      StudioDispatchLedgerStatements statements,
      UITestExecutionRepository executions,
      StudioService studioService,
      StudioExecutionProperties properties,
      ObjectMapper objectMapper,
      List<ReportCommitHook> commitHooks,
      Clock clock) {
    this.statements = statements;
    this.executions = executions;
    this.studioService = studioService;
    this.properties = properties;
    this.objectMapper = objectMapper;
    this.commitHooks = commitHooks == null ? List.of() : List.copyOf(commitHooks);
    this.clock = clock;
  }

  /**
   * A seam that runs inside the report transaction, just before it commits.
   *
   * <p>Production registers none. It exists so that AC-20's "a commit failure injected after the
   * handler's work yields a non-{@code 200}" is decidable at the HTTP boundary rather than asserted
   * by inspection, which is the difference between a tested ordering and an intended one.
   */
  public interface ReportCommitHook {

    void beforeCommit(UUID executionId);
  }

  /** Applies one report. Returns the acknowledgement the route sends after commit. */
  @Transactional
  public ProgressAck apply(UUID pathExecutionId, RunnerReport report) {
    if (secretRevocation != null) secretRevocation.executionRevoked(pathExecutionId);
    registerCommitHooks(pathExecutionId);
    enforceBounds(report);
    requireMatchingIdentity(pathExecutionId, report);

    UITestExecution execution =
        executions
            .findByExecutionId(pathExecutionId)
            .orElseThrow(
                () ->
                    InternalCallbackException.conflict(
                        InternalCallbackCodes.EXECUTION_UNKNOWN,
                        "No execution with this id is accepting reports"));

    boolean cancelled = statements.isCancelRequested(pathExecutionId);
    boolean revoked = statements.find(pathExecutionId).map(row->row.get("revoked_at")!=null).orElse(false);
    boolean observedPreReady =
        execution.getObservedRevisionBinding() != null
            && execution.getBrowserStartedAt() == null
            && !cancelled
            && !revoked
            && !(RunnerReport.STARTED.equals(report.kind())
                && report.browserStartedAt() != null
                && ExecutionStatus.PENDING.equals(execution.getStatus()));
    if (observedPreReady) {
      validateObservedAdmission(execution, report);
      var revision = entityManager.find(UITestRevision.class, execution.getRevisionId());
      if (revision == null) {
        throw observedIdentityRefusal();
      }
      var source = OBSERVED_CONTRACTS.parse(revision.getSource());
      RunnerReportProjection.requireObservedPreReadyFailure(
          report, source.isArray() ? source.size() : 0);
    }
    if (RunnerReport.PROGRESS.equals(report.kind()) && !report.secretUse().isEmpty()) {
      if (execution.getObservedRevisionBinding()==null) throw InternalCallbackException.badRequest(InternalCallbackCodes.INVALID_REPORT,"Secret-use progress requires observed identity");
      validateObservedAdmission(execution,report);
      var revision=entityManager.find(UITestRevision.class,execution.getRevisionId());
      if(revision==null)throw observedIdentityRefusal();
      var artifact=OBSERVED_CONTRACTS.parse(revision.getArtifact());
      var binding=OBSERVED_CONTRACTS.parse(execution.getObservedRevisionBinding());
      if (!java.util.Objects.equals(execution.getBrowserStartedAt(), report.browserStartedAt()) || report.runtimeVersions()==null) throw observedIdentityRefusal();
      try {
        Object reportedProfile=report.runtimeVersions().get("observedProfile"), reportedBuild=report.runtimeVersions().get("observedBuild");
        if (!(reportedProfile instanceof String profile) || !(reportedBuild instanceof String build)
            || !OBSERVED_CONTRACTS.parse(profile).equals(binding.path("requiredProfile"))
            || !OBSERVED_CONTRACTS.parse(build).equals(binding.path("requiredBuild"))) throw observedIdentityRefusal();
      } catch (RuntimeException invalid) { throw observedIdentityRefusal(); }
      if(!binding.path("revisionId").asText().equals(revision.getId().toString())
          || !binding.path("artifactHash").asText().equals(revision.getArtifactHash())
          || !binding.path("artifactHash").asText().equals(com.citi.put.checks.studio.guided.session.GuidedContracts.hash(artifact))) throw observedIdentityRefusal();
      com.citi.put.checks.studio.secrets.ObservedProgressSecretEvidence.require(report,artifact);
    }
    RunnerReportProjection.Projected projected =
        RunnerReportProjection.project(
            report,
            originalSteps(execution),
            properties.evidenceRetentionOrDefault(),
            clock.instant(),
            // Write-once and never cleared, so reading it ahead of the statement cannot be
            // contradicted by it; and a runner can only have been told to cancel after the request
            // committed (ADR-002 §29).
            cancelled,revoked);

    long sequence = report.runnerSequence();
    int applied =
        observedPreReady
            ? applyObservedPreReady(report, projected, execution)
            : applyByKind(report, projected, sequence);

    if (applied == 1) {
      entityManager.clear();
      if (RunnerReport.PROGRESS.equals(report.kind()) && !report.secretUse().isEmpty()) {
        if(secretAudit==null)throw new IllegalStateException("Secret-use progress audit unavailable");
        secretAudit.replayKnownUses(pathExecutionId,report.attemptId(),report.secretUse());
      }
      if (RunnerReport.FINAL.equals(report.kind())) {
        if (secretAudit != null && execution.getObservedRevisionBinding() != null)
          secretAudit.replayTerminal(
              pathExecutionId,
              report.attemptId(),
              report.secretUse());
        afterFinal(report, projected);
      }
      return ack(pathExecutionId, sequence, true);
    }

    // Zero rows. The verdict is already taken; what follows only names it.
    if (statements.isAlreadyApplied(
        report.executionId(),
        report.attemptId(),
        report.admissionId(),
        report.runnerInstanceId(),
        sequence)) {
      // The same owner, the same sequence, re-delivered. 200, applying nothing.
      return ack(pathExecutionId, sequence, false);
    }
    if (RunnerReport.FINAL.equals(report.kind())
        && settleEvidenceOnFinalized(report, projected, sequence) == 1) {
      entityManager.clear();
      afterFinal(report, projected);
      return ack(pathExecutionId, sequence, true);
    }
    throw refusal(pathExecutionId, report, sequence);
  }

  /** Dispatches to the one statement this report kind is applied by. */
  private int applyByKind(
      RunnerReport report, RunnerReportProjection.Projected projected, long sequence) {
    if (RunnerReport.STARTED.equals(report.kind())) {
      return applyStarted(report, projected, sequence);
    }
    if (RunnerReport.PROGRESS.equals(report.kind())) {
      return applyProgress(report, projected, sequence);
    }
    if (RunnerReport.FINAL.equals(report.kind())) {
      return applyFinal(report, projected, sequence);
    }
    return 0;
  }

  private int applyStarted(
      RunnerReport report, RunnerReportProjection.Projected projected, long sequence) {
    if (report.browserStartedAt() == null) {
      // RUNNING is written only by a committed STARTED report that carries a non-null
      // browserStartedAt and comes from the owning admission (§5.1.5, §8.2).
      throw InternalCallbackException.badRequest(
          InternalCallbackCodes.INVALID_REPORT,
          "A STARTED report must carry browserStartedAt; RUNNING is written by nothing else");
    }
    return statements.applyStarted(
        report.executionId(),
        report.attemptId(),
        report.admissionId(),
        report.runnerInstanceId(),
        sequence,
        report.browserStartedAt(),
        writeJson(projected.stepResults()),
        writeJson(projected.logs()),
        projected.logsTruncated(),
        writeJson(projected.runtime()));
  }

  private int applyProgress(
      RunnerReport report, RunnerReportProjection.Projected projected, long sequence) {
    return statements.applyProgress(
        report.executionId(),
        report.attemptId(),
        report.admissionId(),
        report.runnerInstanceId(),
        sequence,
        writeJson(projected.stepResults()),
        writeJson(projected.logs()),
        projected.logsTruncated(),
        writeJson(projected.runtime()));
  }

  private int applyFinal(
      RunnerReport report, RunnerReportProjection.Projected projected, long sequence) {
    if (projected.status() == null) {
      throw InternalCallbackException.badRequest(
          InternalCallbackCodes.INVALID_REPORT, "A FINAL report must carry an outcome");
    }
    return statements.applyFinal(
        report.executionId(),
        report.attemptId(),
        report.admissionId(),
        report.runnerInstanceId(),
        sequence,
        projected.status(),
        projected.errorCode(),
        projected.endedAt(),
        projected.durationMs(),
        writeJson(projected.stepResults()),
        writeJson(withDiagnostic(projected)),
        projected.logsTruncated(),
        writeJson(projected.runtime()),
        projected.videoKey(),
        projected.videoStatus(),
        projected.videoError(),
        projected.videoPartial(),
        projected.videoExpiresAt(),
        projected.manifestKey());
  }

  private int applyObservedPreReady(
      RunnerReport report, RunnerReportProjection.Projected projected, UITestExecution execution) {
    return statements.applyObservedPreReadyFailure(
        report.executionId(),
        report.attemptId(),
        report.admissionId(),
        report.runnerInstanceId(),
        report.runnerSequence(),
        projected.status(),
        projected.errorCode(),
        projected.endedAt(),
        projected.durationMs(),
        writeJson(projected.stepResults()),
        writeJson(withDiagnostic(projected)),
        projected.logsTruncated(),
        writeJson(projected.runtime()),
        projected.videoKey(),
        projected.videoStatus(),
        projected.videoError(),
        projected.videoPartial(),
        projected.videoExpiresAt(),
        projected.manifestKey(),
        execution.getObservedRevisionBinding(),
        execution.getObservedAdmissionReceipt());
  }

  private static InternalCallbackException observedIdentityRefusal() {
    return InternalCallbackException.conflict(
        InternalCallbackCodes.ADMISSION_OWNED, "Observed admission identity mismatch");
  }

  private void validateObservedAdmission(UITestExecution execution, RunnerReport report) {
    var contracts = OBSERVED_CONTRACTS;
    JsonNode binding;
    JsonNode receipt;
    try {
      binding = contracts.parse(execution.getObservedRevisionBinding());
      receipt = contracts.parse(execution.getObservedAdmissionReceipt());
      contracts.validate("v3/replay-job#/definitions/ExecutionBinding", binding);
      contracts.validate("v3/replay-job#/definitions/AdmissionReceipt", receipt);
    } catch (RuntimeException invalid) {
      throw observedIdentityRefusal();
    }
    var request = receipt.path("request");
    var grant = binding.path("replayGrant");
    for (String field :
        List.of(
            "executionId",
            "attemptId",
            "revisionId",
            "revisionDigest",
            "principalId",
            "csiId",
            "scopeHash",
            "currentPolicyHash")) {
      if (!grant.path(field).equals(binding.path(field))) {
        throw observedIdentityRefusal();
      }
    }
    for (String field : List.of("principalId", "csiId", "environment")) {
      if (!binding.path("scope").path(field).equals(binding.path(field))) {
        throw observedIdentityRefusal();
      }
    }
    if (!grant
            .path("profileHash")
            .asText()
            .equals(GuidedContracts.hash(binding.path("requiredProfile")))
        || !grant
            .path("buildHash")
            .asText()
            .equals(GuidedContracts.hash(binding.path("requiredBuild")))
        || !binding
            .path("scopeHash")
            .asText()
            .equals(GuidedContracts.hash(binding.path("scope")))) {
      throw observedIdentityRefusal();
    }

    for (String field :
        List.of(
            "executionId",
            "startedAt",
            "attemptId",
            "revisionId",
            "revisionDigest",
            "artifactHash",
            "configurationHash",
            "learnedPlanHash",
            "referencePolicyHash",
            "publicationEvidenceHash",
            "scopeHash",
            "currentPolicyHash")) {
      if (!request.path(field).equals(binding.path(field))) {
        throw observedIdentityRefusal();
      }
    }
    if (!request.path("profile").equals(binding.path("requiredProfile"))
        || !request.path("build").equals(binding.path("requiredBuild"))
        || !request.path("grantId").equals(binding.path("replayGrant").path("grantId"))
        || !request.path("admissionId").equals(receipt.path("admissionId"))
        || !binding.path("executionId").asText().equals(report.executionId().toString())
        || !binding.path("attemptId").asText().equals(report.attemptId().toString())
        || !request.path("admissionId").asText().equals(report.admissionId().toString())
        || !request.path("runnerInstanceId").asText().equals(report.runnerInstanceId())) {
      throw observedIdentityRefusal();
    }
  }

  /**
   * A later {@code FINAL} that only moves the evidence disposition (AC-25).
   *
   * <p>The outcome is not in the statement's {@code SET} list, so an upload failure can never
   * overwrite a known outcome; {@code streamComplete} flips with a new revision when evidence
   * settles.
   */
  private int settleEvidenceOnFinalized(
      RunnerReport report, RunnerReportProjection.Projected projected, long sequence) {
    if (projected.videoStatus() == null) {
      return 0;
    }
    return statements.settleEvidence(
        report.executionId(),
        report.attemptId(),
        report.admissionId(),
        report.runnerInstanceId(),
        sequence,
        projected.videoKey(),
        projected.videoStatus(),
        projected.videoError(),
        projected.videoPartial(),
        projected.videoExpiresAt(),
        writeJson(withDiagnostic(projected)),
        projected.logsTruncated());
  }

  /**
   * Closes the ledger once outcome <em>and</em> evidence are both settled, and moves the last-run
   * projection forward — and only forward (AC-27).
   */
  private void afterFinal(RunnerReport report, RunnerReportProjection.Projected projected) {
    studioService.applyLastRunProjection(report.executionId());
    if (projected.videoStatus() != null
        && !VideoEvidence.PROCESSING.equals(projected.videoStatus())) {
      statements.closeFinalized(report.executionId());
    }
  }

  /**
   * The bounds §5.4 requires, all from one configuration source (AC-26).
   *
   * <p>{@code logsTruncated} and {@code payloadReduced} are both <b>persisted</b> rather than
   * dropped: they are the API's only record that the runner shed diagnostics to deliver a result it
   * could not replay.
   */
  private void enforceBounds(RunnerReport report) {
    StudioExecutionProperties.Callback bounds = properties.callbackOrDefault();
    int steps = report.steps() == null ? 0 : report.steps().size();
    if (steps > bounds.maxStepsOrDefault()) {
      throw InternalCallbackException.tooLarge(
          InternalCallbackCodes.REPORT_TOO_LARGE,
          "The report carries " + steps + " steps; the bound is " + bounds.maxStepsOrDefault());
    }
    List<com.citi.put.checks.studio.internal.dto.RunnerLogEntry> logs =
        report.logs() == null ? List.of() : report.logs();
    if (logs.size() > bounds.maxLogEntriesOrDefault()) {
      throw InternalCallbackException.tooLarge(
          InternalCallbackCodes.REPORT_TOO_LARGE,
          "The report carries "
              + logs.size()
              + " log entries; the bound is "
              + bounds.maxLogEntriesOrDefault());
    }
    for (com.citi.put.checks.studio.internal.dto.RunnerLogEntry entry : logs) {
      if (entry == null) {
        throw InternalCallbackException.badRequest(
            InternalCallbackCodes.INVALID_REPORT, "Invalid log entry");
      }
      if (entry.message() != null
          && entry.message().length() > bounds.maxLogEntryCharsOrDefault()) {
        throw InternalCallbackException.tooLarge(
            InternalCallbackCodes.REPORT_TOO_LARGE,
            "A log entry is over the " + bounds.maxLogEntryCharsOrDefault() + " character bound");
      }
    }
  }

  private void requireMatchingIdentity(UUID pathExecutionId, RunnerReport report) {
    if (report.executionId() == null || !report.executionId().equals(pathExecutionId)) {
      throw InternalCallbackException.badRequest(
          InternalCallbackCodes.INVALID_REPORT, "The report's executionId does not match the path");
    }
    if (report.attemptId() == null
        || report.admissionId() == null
        || report.runnerInstanceId() == null
        || report.runnerInstanceId().isBlank()) {
      throw InternalCallbackException.badRequest(
          InternalCallbackCodes.INVALID_REPORT,
          "attemptId, admissionId and runnerInstanceId are all required on every report");
    }
  }

  /**
   * Classifies a zero-row verdict, and records a late report for investigation.
   *
   * <p>§5.3: a delayed report "is recorded for investigation; it cannot silently change history or
   * trigger a new run". The record is this log line and nothing else — the history row is left
   * byte-identical, and no run is dispatched.
   */
  private InternalCallbackException refusal(UUID executionId, RunnerReport report, long sequence) {
    Optional<Map<String, Object>> found = statements.find(executionId);
    if (found.isEmpty()) {
      return InternalCallbackException.conflict(
          InternalCallbackCodes.EXECUTION_UNKNOWN, "No execution with this id");
    }
    Map<String, Object> row = found.get();
    String state = String.valueOf(row.get("state"));
    Object attemptId = row.get("attempt_id");
    Object admissionId = row.get("admission_id");
    Object runnerInstanceId = row.get("runner_instance_id");
    long lastSequence = ((Number) row.getOrDefault("last_runner_sequence", 0L)).longValue();

    if (DispatchState.DONE.name().equals(state)) {
      LOGGER.warn(
          "Late Studio runner report recorded for investigation: execution={} attempt={} "
              + "admission={} runner={} kind={} sequence={} arrived after the execution settled; "
              + "history unchanged and no run dispatched",
          executionId,
          report.attemptId(),
          report.admissionId(),
          report.runnerInstanceId(),
          report.kind(),
          sequence);
      return InternalCallbackException.conflict(
          InternalCallbackCodes.EXECUTION_SETTLED,
          "This execution is already settled; the report was recorded for investigation");
    }
    if (attemptId == null || !attemptId.toString().equals(String.valueOf(report.attemptId()))) {
      return InternalCallbackException.conflict(
          InternalCallbackCodes.ATTEMPT_SUPERSEDED, "A different attempt is current");
    }
    if (admissionId == null
        || !admissionId.toString().equals(String.valueOf(report.admissionId()))
        || !String.valueOf(runnerInstanceId).equals(report.runnerInstanceId())) {
      return InternalCallbackException.conflict(
          InternalCallbackCodes.ADMISSION_OWNED,
          "This attempt is owned by a different admission identity");
    }
    if (sequence <= lastSequence) {
      return InternalCallbackException.conflict(
          InternalCallbackCodes.SEQUENCE_REGRESSED,
          "Sequence " + sequence + " is not after the applied " + lastSequence);
    }
    return InternalCallbackException.conflict(
        InternalCallbackCodes.TRANSITION_REJECTED,
        "A " + report.kind() + " report is not a transition state " + state + " permits");
  }

  private ProgressAck ack(UUID executionId, long sequence, boolean applied) {
    long revision =
        executions
            .findByExecutionId(executionId)
            .map(UITestExecution::getSnapshotRevision)
            .orElse(0L);
    return new ProgressAck(
        executionId,
        sequence,
        applied,
        revision,
        statements.isCancelRequested(executionId),
        statements.find(executionId).map(row -> row.get("revoked_at") != null).orElse(false));
  }

  /** The revision's ordered source, which acceptance already wrote one entry per step of. */
  private List<StepResult> originalSteps(UITestExecution execution) {
    String json = execution.getStepResults();
    if (json == null || json.isBlank()) {
      return List.of();
    }
    try {
      List<StepResult> parsed = objectMapper.readValue(json, STEP_RESULTS);
      return parsed == null ? List.of() : List.copyOf(parsed);
    } catch (JsonProcessingException e) {
      throw new IllegalStateException("Stored step_results are not readable", e);
    }
  }

  /** An API-produced diagnostic line, which is where an unmapped runner code lives (AC-16). */
  private List<ExecutionLogEntry> withDiagnostic(RunnerReportProjection.Projected projected) {
    if (projected.diagnostic() == null) {
      return projected.logs();
    }
    List<ExecutionLogEntry> logs = new ArrayList<>(projected.logs());
    String level = ExecutionStatus.ERROR.equals(projected.status()) ? "ERROR" : "INFO";
    logs.add(new ExecutionLogEntry(projected.endedAt(), level, projected.diagnostic(), null));
    return List.copyOf(logs);
  }

  private void registerCommitHooks(UUID executionId) {
    if (commitHooks.isEmpty() || !TransactionSynchronizationManager.isSynchronizationActive()) {
      return;
    }
    TransactionSynchronizationManager.registerSynchronization(
        new TransactionSynchronization() {
          @Override
          public void beforeCommit(boolean readOnly) {
            commitHooks.forEach(hook -> hook.beforeCommit(executionId));
          }
        });
  }

  private String writeJson(Object value) {
    try {
      return objectMapper.writeValueAsString(value);
    } catch (JsonProcessingException e) {
      throw new IllegalStateException("Could not serialize a projected report", e);
    }
  }
