 81	  /** Validate the original coordinates before projection can deduplicate or synthesize entries. */
 82	  static void requireObservedPreReadyFailure(RunnerReport report, int sourceCount) {
 83	    Set<String> reasons =
 84	        Set.of(
 85	            "INVALID_CONTRACT",
 86	            "PROFILE_MISMATCH",
 87	            "POLICY_REFUSED",
 88	            "AUTHORIZATION_EXPIRED",
 89	            "REFERENCE_MISMATCH",
 90	            "PASSWORD_CONTROL_READ_REFUSED",
 91	            "TARGET_DRIFT",
 92	            "TIMEOUT",
 93	            "CANCELLED",
 94	            "INTERNAL_ERROR");
 95	    boolean valid =
 96	        RunnerReport.FINAL.equals(report.kind())
 97	            && report.browserStartedAt() == null
 98	            && report.outcome() != null
 99	            && "ERROR".equals(report.outcome().result())
100	            && "RUN_ERROR".equals(report.outcome().errorCode())
101	            && report.outcome().errorMessage() != null
102	            && reasons.contains(report.outcome().errorMessage())
103	            && sourceCount >= 1
104	            && sourceCount <= 100
105	            && report.steps() != null
106	            && report.steps().size() == sourceCount;
107	    if (valid) {
108	      Set<Integer> coordinates = new java.util.HashSet<>();
109	      for (RunnerStepState step : report.steps()) {
110	        if (step == null
111	            || step.stepIndex() == null
112	            || step.stepIndex() < 0
113	            || step.stepIndex() >= sourceCount
114	            || !coordinates.add(step.stepIndex())
115	            || !StepResult.SKIPPED.equals(step.status())
116	            || step.failure() != null
117	            || step.startedAtMs() != null
118	            || step.finishedAtMs() != null
119	            || step.durationMs() != null) {
120	          valid = false;
121	          break;
122	        }
123	      }
124	    }
125	    if (report.logs() != null
126	        && report.logs().stream().anyMatch(log -> log == null || log.atMs() != null)) {
127	      valid = false;
128	    }
129	    if (!valid) {
130	      throw InternalCallbackException.badRequest(
131	          InternalCallbackCodes.INVALID_REPORT, "Invalid observed pre-Ready terminal report");
132	    }
133	  }
