185	  public static Projected project(RunnerReport report,List<StepResult> original,Duration evidenceRetention,Instant now,boolean cancelRequested,boolean revoked) {
186	    validate(report);
187	
188	    String terminalErrorCode = report.outcome()==null ? null : RunnerOutcomeCodes.errorCodeFor(report.outcome().result(),report.outcome().errorCode(),cancelRequested,revoked);
189	    List<StepResult> stepResults = projectSteps(report, original, terminalErrorCode);
190	    List<ExecutionLogEntry> logs = projectLogs(report, original.size());
191	    RuntimeVersions runtime = projectRuntime(report.runtimeVersions());
192	
193	    String status = null;
194	    String errorCode = null;
195	    String diagnostic = null;
196	    Instant endedAt = null;
197	    Integer durationMs = null;
198	    if (report.outcome() != null) {
199	      status = RunnerOutcomeCodes.statusFor(report.outcome().result());
200	      errorCode = terminalErrorCode;
201	      diagnostic = diagnostic(report);
202	      endedAt = report.reportedAt();
203	      durationMs = browserDurationMs(report);
204	    }
205	
206	    String videoKey = null;
207	    String videoStatus = null;
208	    String videoError = null;
209	    Boolean videoPartial = null;
210	    Instant videoExpiresAt = null;
211	    String manifestKey = null;
212	    if (report.evidence() != null) {
213	      videoKey = report.evidence().videoKey();
214	      videoStatus = projectEvidenceState(report.evidence().state());
215	      // The reported value, never a constant (O-13, ADR-002 §17.5). Absent means false — which is
216	      // defence in depth rather than the only protection, because the merged runner declares
217	      // `partial` non-optionally and "absent" is unreachable from it.
218	      videoPartial = Boolean.TRUE.equals(report.evidence().partial());
219	      manifestKey = report.evidence().manifestKey();
220	      if (VideoEvidence.AVAILABLE.equals(videoStatus)) {
221	        // AVAILABLE and EXPIRED are the API's judgment against retention, never the runner's:
222	        // it holds no Get and no List permission and can observe neither (§6.1, §6.2).
223	        videoExpiresAt = now.plus(evidenceRetention);
224	      }
225	      if (VideoEvidence.FAILED.equals(videoStatus)) {
226	        videoError = "The runner reported that evidence could not be stored";
227	      }
228	    }
229	
230	    return new Projected(
231	        stepResults,
232	        logs,
233	        Boolean.TRUE.equals(report.logsTruncated()),
234	        runtime,
235	        status,
236	        errorCode,
237	        diagnostic,
238	        endedAt,
239	        durationMs,
240	        videoKey,
241	        videoStatus,
242	        videoError,
243	        videoPartial,
244	        videoExpiresAt,
245	        manifestKey);
246	  }
