 82	  /** Account freshness precedes the admission transaction; SQL rechecks exact stored authority. */
 83	  public AdmissionPermit prepareAdmission(UUID id, JsonNode request) {
 84	    require(
 85	        !TransactionSynchronizationManager.isActualTransactionActive(),
 86	        "RUNTIME_INCOMPATIBLE",
 87	        409);
 88	    contracts.validate("v3/replay-job#/definitions/AdmissionRequest", request);
 89	    require(text(request, "executionId").equals(id.toString()), "FORBIDDEN_SCOPE", 403);
 90	    JsonNode binding =
 91	        binding(id).orElseThrow(() -> new GuidedSessionException("FORBIDDEN_SCOPE", 403));
 92	    check(binding);
 93	    for (String field :
 94	        List.of(
 95	            "executionId",
 96	            "startedAt",
 97	            "attemptId",
 98	            "revisionId",
 99	            "revisionDigest",
100	            "artifactHash",
101	            "configurationHash",
102	            "learnedPlanHash",
103	            "referencePolicyHash",
104	            "publicationEvidenceHash",
105	            "scopeHash",
106	            "currentPolicyHash")) {
107	      require(request.path(field).equals(binding.path(field)), "FORBIDDEN_SCOPE", 403);
108	    }
109	    require(
110	        request.path("profile").equals(binding.path("requiredProfile"))
111	            && request.path("build").equals(binding.path("requiredBuild"))
112	            && request.path("grantId").equals(binding.path("replayGrant").path("grantId")),
113	        "FORBIDDEN_SCOPE",
114	        403);
115	    Instant expiry = Instant.parse(text(binding.path("replayGrant"), "expiresAt"));
116	    Instant authorizationCheck = PublicationContracts.millisecond(clock.instant().plusMillis(5000));
117	    if (expiry.isAfter(authorizationCheck)) {
118	      expiry = authorizationCheck;
119	    }
120	    return new AdmissionPermit(request, binding, expiry);
121	  }
