142	  /** Fresh attempt only after a proven definite refusal or an audited zero-send Vault outage. */
143	  public JsonNode refreshRetry(JsonNode accepted, String owner) {
144	    require(
145	        TransactionSynchronizationManager.isActualTransactionActive(), "RUNTIME_INCOMPATIBLE", 409);
146	    UUID id = UUID.fromString(text(accepted, "executionId"));
147	    var rows =
148	        jdbc.queryForList(
149	            "SELECT l.*,e.observed_admission_receipt FROM studio_dispatch_ledger l JOIN ui_test_executions e ON e.id=l.execution_id AND e.started_at=l.execution_accepted_at WHERE l.execution_id=? FOR UPDATE OF l,e",
150	            id);
151	    require(rows.size() == 1, "FORBIDDEN_SCOPE", 403);
152	    var row = rows.getFirst();
153	    Object definite = row.get("definite_refusal_attempt_id"),
154	        zeroSend = row.get("zero_send_decision_attempt_id");
155	    Object token =
156	        definite != null && definite.toString().equals(text(accepted, "attemptId"))
157	            ? definite
158	            : zeroSend != null && zeroSend.toString().equals(text(accepted, "attemptId"))
159	                ? zeroSend
160	                : null;
161	    if (token == null) return accepted;
162	    require(
163	        "CLAIMED".equals(row.get("state"))
164	            && owner.equals(row.get("lease_owner"))
165	            && row.get("attempt_id") == null
166	            && row.get("admission_id") == null
167	            && row.get("observed_admission_receipt") == null
168	            && token.toString().equals(text(accepted, "attemptId")),
169	        "FORBIDDEN_SCOPE",
170	        403);
171	    ObjectNode fresh = PublicationContracts.copy(accepted);
172	    String attempt = UUID.randomUUID().toString();
173	    fresh.put("attemptId", attempt);
174	    ObjectNode grant = PublicationContracts.copy(accepted.path("replayGrant"));
175	    Instant issued = PublicationContracts.millisecond(clock.instant());
176	    grant
177	        .put("grantId", UUID.randomUUID().toString())
178	        .put("attemptId", attempt)
179	        .put("issuedAt", PublicationContracts.time(issued))
180	        .put(
181	            "expiresAt",
182	            PublicationContracts.time(issued.plusMillis(properties.authorizationTtlMs())));
183	    fresh.set("replayGrant", grant);
184	    check(fresh);
185	    jdbc.queryForObject(
186	        "SELECT set_config('studio.observed_retry_owner',?,true)", String.class, owner);
187	    int changed =
188	        jdbc.update(
189	            "UPDATE ui_test_executions e SET observed_revision_binding=?::jsonb FROM studio_dispatch_ledger l WHERE e.id=l.execution_id AND e.started_at=l.execution_accepted_at AND l.execution_id=? AND l.state='CLAIMED' AND l.lease_owner=? AND l.lease_expires_at>clock_timestamp() AND l.attempt_id IS NULL AND l.admission_id IS NULL AND e.observed_admission_receipt IS NULL AND (l.definite_refusal_attempt_id=? OR l.zero_send_decision_attempt_id=?)",
190	            fresh.toString(),
191	            id,
192	            owner,
193	            UUID.fromString(token.toString()),
194	            UUID.fromString(token.toString()));
195	    require(changed == 1, "FORBIDDEN_SCOPE", 403);
196	    return fresh;
197	  }
