317	  public ResolvedJob job(
318	      JsonNode binding,
319	      Map<String, String> plainValues,
320	      com.citi.put.checks.studio.dispatch.StudioReferenceResolver.ValueReadEntry readEntry) {
321	    require(
322	        !TransactionSynchronizationManager.isActualTransactionActive(),
323	        "RUNTIME_INCOMPATIBLE",
324	        409);
325	    var acceptedDeclarations = new java.util.LinkedHashSet<String>();
326	    var immutableReferences =
327	        contracts.parse(
328	            jdbc.queryForObject(
329	                "SELECT \"references\"::text FROM ui_test_revisions WHERE id=?",
330	                String.class,
331	                UUID.fromString(text(binding, "revisionId"))));
332	    for (JsonNode id : immutableReferences.path("secrets")) acceptedDeclarations.add(id.asText());
333	    boolean resolutionEntered = false;
334	    try {
335	      check(binding);
336	      JsonNode verified = verifier.verify(UUID.fromString(text(binding, "revisionId")));
337	      require(
338	          verified
339	                  .path("artifact")
340	                  .path("configurationHash")
341	                  .equals(binding.path("configurationHash"))
342	              && GuidedContracts.hash(verified.path("artifact"))
343	                  .equals(text(binding, "artifactHash")),
344	          "EVIDENCE_MISMATCH",
345	          409);
346	      ObjectNode job = contracts.object().put("schemaVersion", 3).put("kind", "observed");
347	      job.set("binding", binding.deepCopy());
348	      job.set("artifact", verified.path("artifact"));
349	      job.set("configuration", verified.path("configuration"));
350	      var inputs = job.putArray("inputs");
351	      JsonNode authoring =
352	          contracts.parse(
353	              jdbc.queryForObject(
354	                  "SELECT authoring::text FROM ui_test_revisions WHERE id=?",
355	                  String.class,
356	                  UUID.fromString(text(binding, "revisionId"))));
357	      for (JsonNode recipe : verified.path("artifact").path("inputRecipes")) {
358	        if (recipe.path("kind").asText().equals("secretRef")) continue;
359	        JsonNode provenance = recipe.path("provenance");
360	        String value;
361	        if (provenance.path("kind").asText().equals("sourceSpan")) {
362	          JsonNode step =
363	              GuidedPlanBuilder.unique(authoring.path("steps"), "id", text(recipe, "stepId"));
364	          String source = text(step, "text");
365	          int start = provenance.path("start").asInt(-1), end = provenance.path("end").asInt(-1);
366	          require(start >= 0 && end > start && end <= source.length(), "REFERENCE_MISMATCH", 422);
367	          value = source.substring(start, end);
368	        } else {
369	          value = plainValues.get(text(provenance, "referenceName"));
370	          require(value != null, "REFERENCE_MISMATCH", 422);
371	        }
372	        inputs.addObject().put("inputId", text(recipe, "inputId")).put("value", value);
373	      }
374	      job.putObject("runtime")
375	          .put(
376	              "stepTimeoutMs",
377	              verified.path("configuration").path("timeoutSeconds").asLong() * 1000L)
378	          .put("totalRuntimeMs", execution.totalRuntimeOrDefault().toMillis());
379	      // Ordinary explicit recording geometry remains distinct from the authored viewport.
380	      job.putObject("recording")
381	          .put("width", properties.recordingWidth())
382	          .put("height", properties.recordingHeight());
383	      job.putObject("secrets");
384	      job.putObject("secretOrigins");
385	      contracts.validate("v3/replay-job", job);
386	      PublicationContracts.bounded(job, properties.maxJobBytes());
387	      check(binding);
388	      for (JsonNode recipe : verified.path("artifact").path("inputRecipes"))
389	        if (recipe.path("kind").asText().equals("secretRef"))
390	          require(
391	              acceptedDeclarations.contains(text(recipe.path("provenance"), "referenceName")),
392	              "REFERENCE_MISMATCH",
393	              422);
394	      var typedDeclarations =
395	          new com.citi.put.checks.studio.dispatch.ReferenceDeclarations(
396	              List.of(), List.copyOf(acceptedDeclarations));
397	      resolutionEntered = true;
398	      var resolved =
399	          acceptedDeclarations.isEmpty()
400	              ? references.resolve(
401	                  text(binding, "csiId"),
402	                  text(binding, "environment"),
403	                  UUID.fromString(text(binding, "testId")),
404	                  text(binding, "principalId"),
405	                  typedDeclarations)
406	              : references.resolve(
407	                  text(binding, "csiId"),
408	                  text(binding, "environment"),
409	                  UUID.fromString(text(binding, "testId")),
410	                  text(binding, "principalId"),
411	                  typedDeclarations,
412	                  trackedReadEntry(binding, readEntry));
413	      try {
414	        verifier.assertResolvedSecretLiterals(
415	            verified.path("artifact"), resolved, job.path("inputs"));
416	        job.set(
417	            "secretOrigins",
418	            new com.fasterxml.jackson.databind.ObjectMapper()
419	                .valueToTree(resolved.secretOrigins()));
420	        return new ResolvedJob(job, resolved);
421	      } catch (RuntimeException failure) {
422	        var decisions =
423	            new java.util.LinkedHashMap<
424	                String, com.citi.put.checks.studio.dispatch.StudioReferenceResolver.Decision>();
425	        resolved
426	            .secretVersions()
427	            .forEach(
428	                (id, version) ->
429	                    decisions.put(
430	                        id,
431	                        new com.citi.put.checks.studio.dispatch.StudioReferenceResolver.Decision(
432	                            com.citi.put.checks.studio.dispatch.StudioReferenceResolver
433	                                .DecisionOutcome.RESOLVED,
434	                            version)));
435	        com.citi.put.checks.studio.dispatch.StudioReferenceResolver.attachDecisionFacts(
436	            failure, decisions);
437	        resolved.close();
438	        throw failure;
439	      }
440	    } catch (RuntimeException failure) {
441	      if (!resolutionEntered)
442	        com.citi.put.checks.studio.dispatch.StudioReferenceResolver.attachDecisionFacts(
443	            failure, Map.of(), acceptedDeclarations);
444	      throw failure;
445	    }
446	  }
447	}

