145	  /**
146	   * One pass. Returns how many rows it dispatched.
147	   *
148	   * <p>The pass begins by relaying recorded cancels (Studio v1 WP4), whatever the kill switch says:
149	   * the switch stops new browser work, and a cancel only ever stops browser work that already
150	   * exists.
151	   */
152	  public int dispatchOnce() {
153	    relayCancels();
154	    if (!properties.enabledOrDefault()) {
155	      return closeUndispatchedWork();
156	    }
157	    StudioExecutionProperties.Dispatcher budget = properties.dispatcherOrDefault();
158	    int batchSize = budget.batchSizeOrDefault();
159	    Set<UUID> attempted = new HashSet<>();
160	    int dispatched = 0;
161	    // One row per claim, immediately before its own dispatch: the lease clock of each row starts
162	    // when that row is taken, exactly as it did when the pass claimed ids one by one. Claiming the
163	    // whole batch up front would start every lease at the top of the pass, and a slow send ahead
164	    // of a row could expire that row's lease before it was ever attempted.
165	    for (int taken = 0; taken < batchSize; taken++) {
166	      Instant now = clock.instant();
167	      Instant leaseExpiresAt = now.plus(budget.leaseOrDefault());
168	      List<UUID> claimed =
169	          transactions.execute(
170	              status -> statements.claimQueued(instanceId, leaseExpiresAt, now, 1, attempted));
171	      if (claimed == null || claimed.isEmpty()) {
172	        break;
173	      }
174	      UUID executionId = claimed.get(0);
175	      attempted.add(executionId);
176	      if (dispatchClaimed(executionId, now)) {
177	        dispatched++;
178	      }
179	    }
180	    return dispatched;
181	  }
