183	  /**
184	   * The kill switch's second property (AC-11): queued undispatched work is closed
185	   * <em>explicitly</em> rather than left to a deadline. Admitted, running and finalizing rows are
186	   * untouched and their reports are still accepted and applied. The closure is idempotent, so a
187	   * second pass changes nothing and bumps no revision, and re-enabling does not resurrect a closed
188	   * row.
189	   */
190	  public int closeUndispatchedWork() {
191	    List<UUID> undispatched =
192	        jdbc.queryForList(
193	            """
194	            SELECT execution_id FROM studio_dispatch_ledger
195	             WHERE state IN ('QUEUED', 'CLAIMED')
196	             ORDER BY execution_accepted_at
197	             LIMIT ?
198	            """,
199	            UUID.class,
200	            properties.dispatcherOrDefault().batchSizeOrDefault());
201	    int closed = 0;
202	    for (UUID executionId : undispatched) {
203	      Integer applied =
204	          transactions.execute(
205	              status ->
206	                  statements.closeUndispatchedWithError(
207	                      executionId, ExecutionErrorCode.DISPATCH_DISABLED, clock.instant()));
208	      if (applied != null && applied == 1) {
209	        closed++;
210	      }
211	    }
212	    return closed;
213	  }
