218	   *
219	   * <p>One {@code DELETE /v1/runs/{id}} per row per pass. An acknowledged relay — {@code 202}, or
220	   * {@code 409} for a run that had already finished — is recorded so no later pass repeats it. An
221	   * unacknowledged one is left for the next pass, because a {@code 404} can mean the request
222	   * reached a runner pod that does not hold the run; the running reaper bounds how long that goes
223	   * on by closing the cancel itself.
224	   *
225	   * <p>The relay never writes an outcome. The run ends when the runner's {@code FINAL} report lands
226	   * through the ordinary report path, or when the reaper closes it.
227	   */
228	  public int relayCancels() {
229	    int acknowledged = 0;
230	    for (UUID executionId :
231	        statements.findCancelsToRelay(properties.dispatcherOrDefault().batchSizeOrDefault())) {
232	      RunnerDispatchClient.CancelOutcome outcome = runnerClient.cancel(executionId);
233	      if (outcome != null && outcome.settled()) {
234	        Integer marked =
235	            transactions.execute(
236	                status -> statements.markCancelRelayed(executionId, clock.instant()));
237	        if (marked != null && marked == 1) {
