239	        }
240	      } else {
241	        LOGGER.info(
242	            "Studio cancel of execution {} not acknowledged by the runner ({}); the next pass "
243	                + "retries it",
244	            executionId,
245	            outcome);
246	      }
247	    }
248	    return acknowledged;
249	  }
