265	  /**
266	   * Everything after the claim, for a row this dispatcher has just claimed at {@code now}. Returns
267	   * true when a send left the process.
268	   */
269	  private boolean dispatchClaimed(UUID executionId, Instant now) {
270	    Map<String, Object> row = statements.find(executionId).orElse(null);
271	    if (row == null) {
272	      return false;
273	    }
274	    UUID testId = (UUID) row.get("test_id");
275	    String csiId = String.valueOf(row.get("csi_id"));
276	    String principal = (String) row.get("principal");
277	    Instant pendingDeadline = instant(row.get("pending_deadline_at"));
278	
279	    if (pendingDeadline != null && !pendingDeadline.isAfter(now)) {
280	      close(executionId, ExecutionErrorCode.DISPATCH_FAILED, now);
281	      return false;
282	    }
283	
284	    if (observed == null
285	        && Boolean.TRUE.equals(
286	            jdbc.queryForObject(
287	                "SELECT EXISTS(SELECT 1 FROM ui_test_executions e JOIN studio_dispatch_ledger l ON l.execution_id=e.id AND l.execution_accepted_at=e.started_at WHERE l.execution_id=? AND e.observed_revision_binding IS NOT NULL)",
288	                Boolean.class,
289	                executionId))) {
290	      close(executionId, ExecutionErrorCode.DISPATCH_FAILED, now);
291	      return false;
292	    }
293	    if (observed != null) {
294	      var binding = observed.binding(executionId);
295	      if (binding.isPresent()) {
296	        return dispatchObserved(executionId, binding.get(), now);
297	      }
298	    }
299	
300	    String policyIdentity;
301	    try {
302	      policyIdentity = authorization.recheck(executionId, testId, csiId, principal);
303	    } catch (DispatchAuthorization.AuthorizationRevokedException e) {
304	      // A revoked permission is terminal with an explicit code, never a retry and never a skip.
305	      LOGGER.warn("Studio dispatch refused for execution {}: {}", executionId, e.getMessage());
306	      close(executionId, ExecutionErrorCode.AUTHORIZATION_REVOKED, now);
307	      return false;
308	    }
309	
310	    UUID revisionId = revisionIdOf(executionId);
311	    String environment = environmentOf(executionId);
312	
313	    UITestRevision revision;
314	    ReferenceDeclarations declarations;
315	    try {
316	      revision = revisionId == null ? null : revisions.findById(revisionId).orElse(null);
317	      if (revision == null) {
318	        throw new ExecutionReferences.UnreadableReferenceDeclarationException(
319	            "the confirmed revision this execution snapshotted cannot be read");
320	      }
321	      declarations = ExecutionReferences.declared(objectMapper, revision.getReferences());
322	    } catch (ExecutionReferences.UnreadableReferenceDeclarationException e) {
323	      // Terminal, not an empty set. The previous `orElse(List.of())` made an unreadable revision a
324	      // run with no references and no secrets — for a login test, a browser opening a real
325	      // application with an empty password field. @po ruled the code REFERENCE_UNAVAILABLE
326	      // (ADR-002 §15.3: a fact about the draft and its environment). The message names the
327	      // declaration and never the revision's contents (AC-6, AC-10).
328	      LOGGER.warn("Studio dispatch refused for execution {}: {}", executionId, e.getMessage());
329	      close(executionId, ExecutionErrorCode.REFERENCE_UNAVAILABLE, now);
330	      return false;
331	    }
332	
333	    UUID attemptId = UUID.randomUUID();
334	    DispatchOutcome outcome;
335	    // Resolution happens here and nowhere else, and the values leave this block only on the wire.
336	    try (StudioReferenceResolver.Resolved resolved =
337	        references.resolve(csiId, environment, testId, principal, secretsOnly(declarations))) {
338	      recordDispatchPolicy(executionId, policyIdentity, resolved.secretVersions());
339	      Map<String, String> plainVariables = plainVariablesOf(executionId, declarations);
340	
341	      RunJob job;
342	      try {
343	        job =
344	            job(
345	                executionId,
346	                attemptId,
347	                testId,
348	                csiId,
349	                revision,
350	                declarations,
351	                plainVariables,
352	                resolved);
353	      } catch (IllegalStateException e) {
354	        // The revision's artifact or configuration document could not be read. Not a reference
355	        // condition, so it does not borrow a reference code; it is a dispatch that could not be
356	        // made. The message never carries the document.
357	        LOGGER.warn("Studio dispatch failed for execution {}: {}", executionId, e.getMessage());
358	        close(executionId, ExecutionErrorCode.DISPATCH_FAILED, now);
359	        return false;
360	      }
361	
362	      Integer began =
363	          transactions.execute(
364	              status -> statements.beginDispatch(executionId, instanceId, attemptId));
365	      if (began == null || began != 1) {
366	        return false;
367	      }
368	      // The transaction above has committed. The send happens strictly after it, so a crash here
369	      // leaves a committed attempt with no send — which §5.1 permits to end as unknown rather
370	      // than be replayed into a duplicate browser.
371	      outcome = runnerClient.send(job);
372	    } catch (StudioReferenceResolver.SecretUseRevokedException e) {
373	      // A fact about the principal (ADR-002 §15.2). The send never happened.
374	      LOGGER.warn("Studio dispatch refused for execution {}: {}", executionId, e.getMessage());
375	      close(executionId, ExecutionErrorCode.AUTHORIZATION_REVOKED, now);
376	      return false;
377	    } catch (VaultProviderUnavailableException e) {
378	      // No attempt was issued and no send occurred. A Vault outage is transient infrastructure,
379	      // not proof that the reference vanished; release the claim so the next pass can retry until
380	      // the existing pending deadline makes the final decision.
381	      LOGGER.warn(
382	          "Studio dispatch deferred for execution {} because Vault is unavailable", executionId);
383	      transactions.execute(status -> statements.releaseClaim(executionId));
384	      return false;
385	    } catch (
386	        com.citi.put.checks.studio.secrets.VaultStudioReferenceResolver.SecretTooLongException e) {
387	      close(executionId, ExecutionErrorCode.SECRET_TOO_LONG, now);
388	      return false;
389	    } catch (StudioReferenceResolver.ReferenceUnavailableException e) {
390	      LOGGER.warn("Studio dispatch refused for execution {}: {}", executionId, e.getMessage());
391	      close(executionId, ExecutionErrorCode.REFERENCE_UNAVAILABLE, now);
392	      return false;
393	    }
394	
395	    applyOutcome(executionId, attemptId, outcome, pendingDeadline, now);
396	    return true;
397	  }
