437	            now);
438	        return true;
439	      }
440	    } catch (VaultProviderUnavailableException failure) {
441	      settleObservedFailure(binding, failure, null, now);
442	      return false;
443	    } catch (StudioReferenceResolver.SecretUseRevokedException failure) {
444	      settleObservedFailure(binding, failure, ExecutionErrorCode.AUTHORIZATION_REVOKED, now);
