   501	  /** Genuine pre-send decision and its owner transition commit or roll back as one unit. */
   502	  void settleObservedFailure(
   503	      JsonNode binding, RuntimeException failure, String failureCode, Instant now) {
   504	    UUID id = UUID.fromString(binding.path("executionId").asText());
   505	    UUID attempt = UUID.fromString(binding.path("attemptId").asText());
   506	    transactions.executeWithoutResult(
   507	        status -> {
   508	          if (!statements.lockObservedResolutionOwner(id, instanceId, attempt)) return;
   509	          var owner = statements.find(id).orElseThrow();
   510	          String code =
   511	              owner.get("cancel_requested_at") != null
   512	                  ? ExecutionErrorCode.CANCELLED
   513	                  : owner.get("revoked_at") != null
   514	                      ? ExecutionErrorCode.AUTHORIZATION_REVOKED
   515	                      : failureCode;
   516	          auditObservedFailure(binding, failure);
   517	          if (java.util.Arrays.stream(failure.getSuppressed())
   518	              .anyMatch(StudioReferenceResolver.ResolutionFacts.class::isInstance)) {
   519	            if (secretAudit == null)
   520	              throw new IllegalStateException("Missing secret no-send audit");
   521	            secretAudit.replayNoSendDecision(
   522	                binding,
   523	                instanceId,
   524	                StudioReferenceResolver.positivelyNotEntered(failure),
   525	                code == null
   526	                    ? com.citi.put.checks.studio.secrets.SecretUseAuditRecorder.NoSendDisposition
   527	                        .REQUEUED
   528	                    : com.citi.put.checks.studio.secrets.SecretUseAuditRecorder.NoSendDisposition
   529	                        .CLOSED);
   530	          }
   531	          int applied =
   532	              code == null
   533	                  ? statements.releaseObservedOutageClaim(id, instanceId, attempt)
   534	                  : statements.closeWithError(id, code, now);
   535	          if (applied != 1)
   536	            throw new IllegalStateException("Observed failure decision lost its owner transition");
   537	        });
   538	  }
