   540	  private static String observedRefusalCode(RuntimeException refusal) {
   541	    if (!(refusal instanceof com.citi.put.checks.studio.guided.session.GuidedSessionException))
   542	      return ExecutionErrorCode.DISPATCH_FAILED;
   543	    if ("CANCELLED".equals(refusal.getMessage())) return ExecutionErrorCode.CANCELLED;
   544	    return java.util.Set.of(
   545	                "AUTHORIZATION_EXPIRED",
   546	                "FORBIDDEN_SCOPE",
   547	                "SECRET_USE_REVOKED",
   548	                "SECRET_USE_NOT_AUTHORIZED")
   549	            .contains(refusal.getMessage())
   550	        ? ExecutionErrorCode.AUTHORIZATION_REVOKED
   551	        : ExecutionErrorCode.DISPATCH_FAILED;
   552	  }
