   554	  private void auditObservedFailure(JsonNode binding, RuntimeException failure) {
   555	    if (!org.springframework.transaction.support.TransactionSynchronizationManager
   556	        .isActualTransactionActive())
   557	      throw new IllegalStateException("Observed failure audit requires its owner transaction");
   558	    if (secretAudit == null) return;
   559	    var decisions = StudioReferenceResolver.decisionFacts(failure);
   560	    if (decisions.isEmpty()) return;
   561	    var declared =
   562	        ExecutionReferences.declared(
   563	            objectMapper,
   564	            jdbc.queryForObject(
   565	                "SELECT \"references\"::text FROM ui_test_revisions WHERE id=?",
   566	                String.class,
   567	                UUID.fromString(binding.path("revisionId").asText())));
   568	    if (!declared.secrets().containsAll(decisions.keySet()))
   569	      throw new IllegalArgumentException("Undeclared secret decision metadata");
   570	    decisions.forEach(
   571	        (id, decision) ->
   572	            secretAudit.replayRelease(
   573	                binding,
   574	                List.of(id),
   575	                decision.version() == null ? Map.of() : Map.of(id, decision.version()),
   576	                com.citi.put.checks.studio.secrets.SecretUseAuditRecorder.ResolutionOutcome.valueOf(
   577	                    decision.outcome().name())));
   578	    secretAudit.replayNoSend(
   579	        UUID.fromString(binding.path("executionId").asText()),
   580	        UUID.fromString(binding.path("attemptId").asText()));
   581	  }
