   583	  /**
   584	   * The three outcomes (AC-15). The ambiguous branch deliberately does nothing at all: no second
   585	   * send, no second attempt, no state change. The row stays {@code DISPATCHING} and recovery owns
   586	   * it.
   587	   */
   588	  private void applyOutcome(
   589	      UUID executionId,
   590	      UUID attemptId,
   591	      DispatchOutcome outcome,
   592	      Instant pendingDeadline,
   593	      Instant now) {
   594	    switch (outcome.kind()) {
   595	      case ACCEPTED -> {
   596	        // Nothing to write: the admission CAS is the next durable step and the runner owns it.
   597	      }
   598	      case DEFINITE_REFUSAL -> {
   599	        boolean withinDeadline = pendingDeadline == null || pendingDeadline.isAfter(now);
   600	        transactions.executeWithoutResult(
   601	            status -> {
   602	              if (!statements.lockUnadmittedDispatch(executionId, attemptId)) return;
   603	              if (secretAudit != null) secretAudit.replayNoSend(executionId, attemptId);
   604	              var owner = statements.find(executionId).orElseThrow();
   605	              String stopCode =
   606	                  owner.get("cancel_requested_at") != null
   607	                      ? ExecutionErrorCode.CANCELLED
   608	                      : owner.get("revoked_at") != null
   609	                          ? ExecutionErrorCode.AUTHORIZATION_REVOKED
   610	                          : null;
   611	              if (stopCode != null) statements.closeWithError(executionId, stopCode, now);
   612	              else if (outcome.retryable() && withinDeadline) {
   613	                statements.returnAfterDefiniteRefusal(executionId, attemptId);
   614	              } else
   615	                statements.closeWithError(executionId, ExecutionErrorCode.DISPATCH_FAILED, now);
   616	            });
   617	      }
   618	      case AMBIGUOUS ->
   619	          LOGGER.warn(
   620	              "Studio dispatch for execution {} attempt {} is ambiguous ({}); it is NOT resent and "
   621	                  + "recovery will resolve it against admission, progress and manifest state",
   622	              executionId,
   623	              attemptId,
   624	              outcome.detail());
   625	      default -> throw new IllegalStateException("Unclassified dispatch outcome");
   626	    }
   627	  }
   628	
   629	  private void close(UUID executionId, String errorCode, Instant now) {
   630	    transactions.execute(status -> statements.closeWithError(executionId, errorCode, now));
   631	  }
