   633	  /**
   634	   * Builds the fourteen-field job the frozen contract declares (§8.4, AC-2).
   635	   *
   636	   * <p>Every field has a source and none is invented: the artifact, its hash, the source lines and
   637	   * the configuration come from the confirmed revision the execution snapshotted (§8.1); the CSI is
   638	   * the execution's own immutable value (§9.1); the references are the revision's typed
   639	   * declaration; the two resolved maps are this dispatch's resolution; the deadlines are §8.5's
   640	   * starting values and the revision's own runtime budget, sent faithfully and clamped nowhere (the
   641	   * clamp is the runner's, 10.13 AC-6); and the two keys are §6.2's templates over immutable
   642	   * execution identity. Deriving a key is not writing an object — the objects are story 10.14's.
   643	   *
   644	   * <p>The resolved {@code char[]}s become {@link String}s here because a JSON body is text. That
   645	   * is the residual AC-15 names rather than claims away: {@code Resolved.close()} still erases the
   646	   * arrays on every exit path, and nothing in this process retains a path to the values after the
   647	   * send, but the serializer's transient buffers cannot be erased by any code.
   648	   */
   649	  private RunJob job(
   650	      UUID executionId,
   651	      UUID attemptId,
   652	      UUID testId,
   653	      String csiId,
   654	      UITestRevision revision,
   655	      ReferenceDeclarations declarations,
   656	      Map<String, String> plainVariables,
   657	      StudioReferenceResolver.Resolved resolved) {
   658	    return new RunJob(
   659	        executionId,
   660	        attemptId,
   661	        revision.getId(),
   662	        revision.getArtifactHash(),
   663	        document(revision.getArtifact(), "artifact"),
   664	        LegacyStudioAdapter.parseSteps(revision.getSource()),
   665	        document(revision.getConfiguration(), "configuration"),
   666	        csiId,
   667	        declarations,
   668	        plainVariables,
   669	        resolved.secretValues(),
   670	        deadlines(revision),
   671	        RunJob.videoKeyFor(csiId, testId, executionId, attemptId),
   672	        RunJob.manifestKeyFor(csiId, testId, executionId, attemptId),
   673	        referencePolicy(revision),
   674	        resolved.secretOrigins());
   675	  }
