   677	  private JsonNode referencePolicy(UITestRevision revision) {
   678	    if (revision.getAuthoring() == null) {
   679	      return null;
   680	    }
   681	    if (revision.getReferencePolicy() == null) {
   682	      throw new IllegalArgumentException("Authoring v2 revision requires recompilation");
   683	    }
   684	    JsonNode policy = document(revision.getReferencePolicy(), "referencePolicy");
   685	    if (!policy.isObject() || policy.path("version").asInt(-1) != 2) {
   686	      throw new IllegalArgumentException("Authoring v2 revision reference policy is corrupt");
   687	    }
   688	    return policy;
