   691	  /**
   692	   * §8.5's admitted-start value and the server's total browser runtime, sent faithfully.
   693	   *
   694	   * <p><b>Two budgets, two sources.</b> {@code deadlines.totalRuntimeMs} is the whole-run cap and
   695	   * comes from {@code studio.execution.total-runtime} (§5.2: "total browser runtime 120 seconds").
   696	   * The revision's {@code configuration.timeoutSeconds} is the <em>per-step</em> timeout, travels
   697	   * untouched on the job's configuration, and is what the runner derives {@code stepTimeoutMs}
   698	   * from. Until this change the total was derived from the per-step value, so every run was killed
   699	   * at the step timeout — thirty seconds — with an orderly stop and a clean recording that ended
   700	   * mid-test. The per-step value is still required to be usable here, because the runner's envelope
   701	   * refuses a job without one and a refusal is cheaper before the send than after.
   702	   *
   703	   * <p>Nothing is clamped here. {@code effectiveRuntimeCapMs(job.deadlines.totalRuntimeMs, maxima)}
   704	   * is the runner's and stays there (10.13 AC-6); two clamps would be two derivations of one bound,
   705	   * which is this epic's most-repeated defect.
   706	   */
   707	  private RunJob.JobDeadlines deadlines(UITestRevision revision) {
   708	    long admittedStartMs = properties.startDeadlineOrDefault().toMillis();
   709	    JsonNode configuration = document(revision.getConfiguration(), "configuration");
   710	    long stepTimeoutSeconds = configuration.path("timeoutSeconds").asLong(0L);
   711	    if (stepTimeoutSeconds <= 0) {
   712	      throw new IllegalStateException(
   713	          "the confirmed revision's configuration declares no usable step timeout");
   714	    }
   715	    long totalRuntimeMs = properties.totalRuntimeOrDefault().toMillis();
   716	    return new RunJob.JobDeadlines(admittedStartMs, totalRuntimeMs);
   717	  }
