 98	      UUID execution, String code, Instant endedAt, boolean newCancelOnly) {
 99	    var rows =
100	        jdbc.queryForList(
101	            "SELECT l.state,l.cancel_requested_at,e.status,e.observed_revision_binding FROM studio_dispatch_ledger l JOIN ui_test_executions e ON e.id=l.execution_id AND e.started_at=l.execution_accepted_at WHERE l.execution_id=? FOR UPDATE OF l,e",
102	            execution);
103	    if (rows.isEmpty()) return false;
104	    var owner = rows.getFirst();
105	    if (owner.get("observed_revision_binding") == null
106	        || !List.of("QUEUED", "CLAIMED").contains(owner.get("state"))
107	        || !"PENDING".equals(owner.get("status"))
108	        || newCancelOnly && owner.get("cancel_requested_at") != null) return false;
109	    if (secretAudit == null)
110	      throw new IllegalStateException("Observed terminal settlement audit unavailable");
111	    return secretAudit.replayTerminalSettlement(execution, code, endedAt);
112	  }
