 78	  public PublicationContracts.Receipt finalizeForUser(
 79	      Authentication caller, HttpServletRequest request, String id, String key, JsonNode body) {
 80	    contracts.validate("v3/publication", body);
 81	    require(key != null && !key.isBlank() && key.length() <= 256, "INVALID_CONTRACT", 422);
 82	    String digest = GuidedContracts.hash(body);
 83	    var previous = publications.receipt(id);
 84	    if (previous.isPresent()) {
 85	      authorization.authorizeReceiptRead(caller, request, previous.get());
 86	      require(
 87	          previous.get().document().path("finalizeDigest").asText().equals(digest),
 88	          "IDEMPOTENCY_CONFLICT",
 89	          409);
 90	      return previous.get();
 91	    }
 92	    require(properties.enabled(), "PUBLICATION_DISABLED", 409);
 93	    require(replay.enabled(), "REPLAY_DISABLED", 409);
 94	    // Current caller/account checks occur without a database lock; final Core proof is refreshed
 95	    // later.
 96	    JsonNode original = sessions.transaction(() -> sessions.lock(id).document().deepCopy());
 97	    access.checkUser(caller, original);
 98	    access.checkCurrent(original);
 99	    Prepared prepared;
100	    try {
101	      prepared = sessions.transaction(() -> prepare(id, key, digest, body));
102	    } catch (GuidedSessionException failure) {
103	      if (failure.getMessage().equals("PUBLICATION_CONFLICT")) {
104	        conflictBeforeClaim(id);
105	      }
106	      throw failure;
107	    }
108	    PublicationContracts.Attempt attempt = prepared.attempt();
109	    try {
110	      if (attempt.status() == PublicationContracts.AttemptStatus.RESERVED) {
111	        sessions.transaction(
112	            () -> {
113	              sessions.lock(id);
114	              return publications.claim(
115	                  id,
116	                  attempt.attemptId(),
117	                  attempt.claimId(),
118	                  prepared.snapshot().hash(),
119	                  clock.instant());
120	            });
121	        ObjectNode outgoing =
122	            contracts
123	                .object()
124	                .put("schemaVersion", 3)
125	                .put("attemptId", attempt.attemptId().toString())
126	                .put("claimId", attempt.claimId().toString())
127	                .put("snapshotHash", prepared.snapshot().hash())
128	                .put("basisHash", prepared.snapshot().identity().path("basisHash").asText());
129	        outgoing.set("requiredProfile", prepared.candidate().artifact().path("profile"));
130	        outgoing.set("requiredBuild", prepared.build());
131	        outgoing.set("artifact", prepared.candidate().artifact());
132	        outgoing.set("validationBasis", prepared.snapshot().basis());
133	        JsonNode verdict;
134	        try {
135	          verdict =
136	              validator.validate(
137	                  outgoing, new PublicationBudget(attempt.validationDeadline(), clock));
138	        } catch (GuidedSessionException failure) {
139	          sessions.transaction(
140	              () -> {
141	                sessions.lock(id);
142	                boolean unknown =
143	                    failure.getMessage().equals("UNKNOWN_OUTCOME")
144	                        || failure.getMessage().equals("EXPIRED");
145	                return publications.finish(
146	                    id,
147	                    attempt.attemptId(),
148	                    attempt.claimId(),
149	                    prepared.snapshot().hash(),
150	                    unknown
151	                        ? PublicationContracts.AttemptStatus.UNKNOWN
152	                        : PublicationContracts.AttemptStatus.REJECTED,
153	                    null,
154	                    unknown ? "VALIDATION_UNKNOWN" : "VALIDATION_REJECTED",
155	                    clock.instant());
156	              });
157	          throw failure;
158	        }
159	        boolean passed = verdict.path("ok").asBoolean();
160	        sessions.transaction(
161	            () -> {
162	              sessions.lock(id);
163	              return publications.finish(
164	                  id,
165	                  attempt.attemptId(),
166	                  attempt.claimId(),
167	                  prepared.snapshot().hash(),
168	                  passed
169	                      ? PublicationContracts.AttemptStatus.VALIDATED
170	                      : PublicationContracts.AttemptStatus.REJECTED,
171	                  passed ? verdict : null,
172	                  passed ? null : "VALIDATION_REJECTED",
173	                  clock.instant());
174	            });
175	        require(passed, "INVALID_CONTRACT", 422);
176	      } else {
177	        require(
178	            attempt.status() == PublicationContracts.AttemptStatus.VALIDATED,
179	            "PUBLICATION_PENDING",
180	            409);
181	      }
182	      // A long validator cannot age a pre-validation identity check into commit authority.
183	      access.checkCurrent(prepared.session());
184	      PublicationContracts.Grant grant =
185	          authorization.authorizePublication(
186	              caller, request, prepared.snapshot(), prepared.session());
187	      return sessions.transaction(
188	          () -> {
189	            require(properties.enabled() && replay.enabled(), "RUNTIME_INCOMPATIBLE", 409);
190	            var currentSession = sessions.lock(id);
191	            var base =
192	                bases.find(id).orElseThrow(() -> new GuidedSessionException("MISSING_SOURCE", 409));
193	            var source = bases.lockCurrent(UUID.fromString(text(base.document(), "testId")));
194	            bases.requireCurrent(base, source);
195	            pins.supported(prepared.candidate().artifact().path("profile"), prepared.build());
196	            var raw = evidence.read(id);
197	            JsonNode basis =
198	                builder.basis(
199	                    base,
200	                    source,
201	                    raw,
202	                    currentSession.document(),
203	                    builder.learningProvenance(raw.document().path("sourceManifest")));
204	            require(
205	                GuidedContracts.hash(basis)
206	                    .equals(prepared.snapshot().identity().path("basisHash").asText()),
207	                "PUBLICATION_CONFLICT",
208	                409);
209	            PublicationContracts.Receipt receipt =
210	                publications.commit(
211	                    new PublicationContracts.Commit(
212	                        id,
213	                        UUID.randomUUID(),
214	                        attempt.attemptId(),
215	                        attempt.claimId(),
216	                        key,
217	                        digest,
218	                        prepared.snapshot(),
219	                        prepared.candidate(),
220	                        grant),
221	                    clock.instant());
222	            lifecycle.publicationCommitted(id);
223	            return receipt;
224	          });
225	    } catch (GuidedSessionException failure) {
226	      if (failure.getMessage().equals("PUBLICATION_CONFLICT")) {
227	        sessions.transaction(
228	            () -> {
229	              sessions.lock(id);
230	              publications.conflict(id, prepared.snapshot().hash(), clock.instant());
231	              return null;
232	            });
233	      }
234	      throw failure;
235	    }
236	  }
