238	  private void conflictBeforeClaim(String id) {
239	    sessions.transaction(
240	        () -> {
241	          var current = sessions.lock(id);
242	          if (publications.receipt(id).isPresent()
243	              || !current.document().path("state").asText().equals("FINALIZING")) {
244	            return null;
245	          }
246	          var base = bases.find(id);
247	          if (base.isEmpty()) {
248	            return null;
249	          }
250	          bases.lockCurrent(UUID.fromString(text(base.get().document(), "testId")));
251	          current.document().put("state", "PUBLICATION_CONFLICT");
252	          current.progress().put("errorCode", "PUBLICATION_CONFLICT");
253	          sessions.save(current);
254	          return null;
255	        });
256	  }
