 44	  public void assertResolvedSecretLiterals(
 45	      JsonNode artifact,
 46	      com.citi.put.checks.studio.dispatch.StudioReferenceResolver.Resolved resolved,
 47	      JsonNode inputs) {
 48	    var secrets = resolved.secretValues();
 49	    for (JsonNode step : artifact.path("steps"))
 50	      for (JsonNode action : step.path("operations")) {
 51	        JsonNode operation = action.path("operation");
 52	        if (operation.path("kind").asText().equals("fill")) {
 53	          JsonNode value = operation.path("value");
 54	          if (value.path("kind").asText().equals("authoredLiteral")) {
 55	            for (JsonNode input : inputs)
 56	              if (input.path("inputId").equals(value.path("sourceInputId")))
 57	                require(
 58	                    secrets.values().stream()
 59	                        .noneMatch(secret -> secret.matches(input.path("value").asText())),
 60	                    "REFERENCE_MISMATCH",
 61	                    422);
 62	          }
 63	          if (value.isTextual() || value.path("kind").asText().equals("literal")) {
 64	            String literal = value.isTextual() ? value.textValue() : value.path("value").asText();
 65	            require(
 66	                secrets.values().stream().noneMatch(secret -> secret.matches(literal)),
 67	                "REFERENCE_MISMATCH",
 68	                422);
 69	          }
 70	        }
 71	      }
 72	  }
