    ObjectNode dispatch=(ObjectNode)fixture.path("secretDispatch").deepCopy();
    ObjectNode metadata=(ObjectNode)dispatch.remove("secret");metadata.remove("value");
    String canary="GUIDED-BYTE-CANARY-"+java.util.UUID.randomUUID();
    SSLContext tls=certificate();
    var server=HttpsServer.create(new InetSocketAddress("localhost",0),0);server.setHttpsConfigurator(new HttpsConfigurator(tls));
    var received=new AtomicReference<byte[]>();var status=new java.util.concurrent.atomic.AtomicInteger(200);
    byte[] outcome=fixture.path("outcome").toString().getBytes(StandardCharsets.UTF_8);
    server.createContext("/",exchange->{byte[] body=exchange.getRequestBody().readAllBytes();received.set(body);exchange.sendResponseHeaders(status.get(),status.get()==200?outcome.length:-1);if(status.get()==200)exchange.getResponseBody().write(outcome);exchange.close();});server.start();
    try {
      var client=new GuidedRunnerClient(URI.create("https://localhost:"+server.getAddress().getPort()),tls,()->"synthetic-controller-token",contracts);
      for(int reply:new int[]{200,503}) {
        status.set(reply);var bytes=new AtomicReference<byte[]>();client.observeRequestBytes(bytes::set);
        char[] chars=canary.toCharArray();var secret=new SecretValue(chars);
        if(reply==200) client.sendSecret(dispatch,metadata,secret);
        else assertThatThrownBy(()->client.sendSecret(dispatch,metadata,secret)).hasMessage("UNKNOWN_OUTCOME");
        assertThat(new String(received.get(),StandardCharsets.UTF_8)).contains(canary);
        assertThat(bytes.get()).containsOnly((byte)0);assertThat(chars).containsOnly('\0');
        assertThat(dispatch.toString()).doesNotContain(canary);assertThat(secret.toString()).isEqualTo("<secret>");
        java.util.Arrays.fill(received.get(),(byte)0);
      }
    } finally {server.stop(0);java.util.Arrays.fill(outcome,(byte)0);}
  }
  private SSLContext certificate() throws Exception {
    run("openssl","req","-x509","-newkey","rsa:2048","-nodes","-keyout",temporary.resolve("key.pem").toString(),"-out",temporary.resolve("cert.pem").toString(),"-days","1","-subj","/CN=localhost","-addext","subjectAltName=DNS:localhost");
    run("openssl","pkcs12","-export","-inkey",temporary.resolve("key.pem").toString(),"-in",temporary.resolve("cert.pem").toString(),"-out",temporary.resolve("fixture.p12").toString(),"-passout","pass:fixture");
    var store=KeyStore.getInstance("PKCS12");try(var in=Files.newInputStream(temporary.resolve("fixture.p12"))){store.load(in,"fixture".toCharArray());}
    var keys=KeyManagerFactory.getInstance(KeyManagerFactory.getDefaultAlgorithm());keys.init(store,"fixture".toCharArray());
    var trust=TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());trust.init(store);
    var tls=SSLContext.getInstance("TLS");tls.init(keys.getKeyManagers(),trust.getTrustManagers(),new SecureRandom());return tls;
  }
  private void run(String... command) throws Exception {var process=new ProcessBuilder(command).redirectErrorStream(true).start();try(var in=process.getInputStream()){in.transferTo(java.io.OutputStream.nullOutputStream());}assertThat(process.waitFor()).isZero();}
}
