            409);
    }
  }
}

@Override
public void checkSourceCurrent(JsonNode session) {
  classifier.requireCurrentPolicy(session.path("scope"));
  JsonNode current = snapshots.lockCurrent(UUID.fromString(session.path("testId").asText()));
