115	    java.util.Comparator<JsonNode> policyOrder =
116	        java.util.Comparator.comparing(
117	                (JsonNode n) -> text(n, "policyRuleId"), ObservedReplayPins::scalarCompare)
118	            .thenComparing(GuidedContracts::canonical, ObservedReplayPins::scalarCompare);
119	    var rules = GuidedPlanBuilder.list(normalized.path("rules"));
120	    rules.sort(policyOrder);
121	    var normalizedRules = normalized.putArray("rules");
122	    rules.forEach(normalizedRules::add);
