125	      var grants = GuidedPlanBuilder.list(app.path("readGrants"));
126	      var types = List.of("text", "search", "email", "tel", "url", "textarea");
127	      for (JsonNode grant : grants) {
128	        if (grant.has("controlValue")) {
129	          var controls = GuidedPlanBuilder.list(grant.path("controlValue").path("types"));
130	          controls.sort(java.util.Comparator.comparingInt(t -> types.indexOf(t.asText())));
131	          var sorted = ((ObjectNode) grant.path("controlValue")).putArray("types");
132	          controls.forEach(sorted::add);
133	        }
134	      }
135	      grants.sort(policyOrder);
136	      var sorted = app.putArray("readGrants");
137	      grants.forEach(sorted::add);
138	    }
139	    return normalized;
140	  }
