142	  private static int scalarCompare(String a, String b) {
143	    var left = a.codePoints().iterator();
144	    var right = b.codePoints().iterator();
145	    while (left.hasNext() && right.hasNext()) {
146	      int c = Integer.compare(left.nextInt(), right.nextInt());
147	      if (c != 0) {
148	        return c;
149	      }
150	    }
151	    return Boolean.compare(left.hasNext(), right.hasNext());
152	  }
