  6	import com.fasterxml.jackson.databind.node.ObjectNode;
  7	
  8	/** Pure policy projection: a frozen graph records requirements, never current execution grants. */
  9	public final class ObservedReferencePolicyDeriver {
 10	  private final GuidedContracts contracts;
 11	
 12	  public ObservedReferencePolicyDeriver(GuidedContracts contracts) {
 13	    this.contracts = contracts;
 14	  }
 15	
 16	  public ObjectNode derive(JsonNode basis, JsonNode plan, JsonNode recipes) {
 17	    ArrayNode admissions = contracts.object().putArray("admissions");
 18	    for (JsonNode fact : basis.path("actions")) {
 19	      JsonNode ledger = fact.path("ledger");
 20	      ObjectNode tuple = admissions.addObject();
 21	      for (String field :
 22	          java.util.List.of("coordinate", "admission", "operationHash", "scopeHash")) {
 23	        tuple.set(field, ledger.path(field));
 24	      }
 25	    }
 26	    ObjectNode evidence =
 27	        contracts
 28	            .object()
 29	            .put("version", 1)
 30	            .put("basisHash", GuidedContracts.hash(basis))
 31	            .put("runAuthorizationHash", GuidedContracts.hash(basis.path("runAuthorization")))
 32	            .put("translationHash", basis.path("translationHash").asText())
 33	            .put("bootstrapHash", GuidedContracts.hash(basis.path("bootstrap")))
 34	            .put("sourceManifestHash", basis.path("sourceManifestHash").asText());
 35	    ObjectNode policy =
 36	        contracts
 37	            .object()
 38	            .put("schemaVersion", 4)
 39	            .put("learnedPlanHash", GuidedContracts.hash(plan))
 40	            .put("admissionProvenanceHash", GuidedContracts.hash(admissions))
 41	            .put("publicationEvidenceHash", GuidedContracts.hash(evidence))
 42	            .put("runAuthorizationHash", GuidedContracts.hash(basis.path("runAuthorization")));
 43	    policy.set("scope", basis.path("replayRequirements").deepCopy());
 44	    policy.set("inputs", recipes.deepCopy());
 45	    policy.set("bindings", basis.path("bindings").deepCopy());
 46	    policy.set("transfers", basis.path("transfers").deepCopy());
 47	    return policy;
 48	  }
 49	}

