171	-- VOLATILE is deliberate: after a waited owner lock, SPI reads use the fresh current snapshot.
172	CREATE FUNCTION studio_observed_terminal_classification(execution_key uuid,attempt_key uuid) RETURNS jsonb
173	 LANGUAGE plpgsql VOLATILE AS $$
174	DECLARE result jsonb; declarations jsonb; owner_row studio_dispatch_ledger; history_row ui_test_executions;
175	BEGIN
176	 SELECT * INTO STRICT owner_row FROM studio_dispatch_ledger WHERE execution_id=execution_key;
177	 SELECT * INTO STRICT history_row FROM ui_test_executions WHERE id=execution_key AND started_at=owner_row.execution_accepted_at;
178	 IF EXISTS(SELECT 1 FROM studio_observed_secret_read_entries entry WHERE entry.execution_id=execution_key
179	  AND entry.attempt_id=attempt_key AND ROW(entry.execution_accepted_at,entry.revision_id,entry.revision_digest::text,
180	   entry.binding_digest::text,entry.scope_hash::text,entry.principal_id,entry.csi_id,entry.environment,entry.test_id)
181	   IS DISTINCT FROM ROW(owner_row.execution_accepted_at,history_row.revision_id,
182	    history_row.observed_revision_binding->>'revisionDigest',studio_publication_hash(history_row.observed_revision_binding),
183	    history_row.observed_revision_binding->>'scopeHash',owner_row.principal,owner_row.csi_id,history_row.environment,owner_row.test_id)) THEN
184	  RAISE EXCEPTION 'terminal secret read-entry scope mismatch'; END IF;
185	 SELECT r."references"->'secrets' INTO STRICT declarations FROM studio_dispatch_ledger l
186	  JOIN ui_test_executions e ON e.id=l.execution_id AND e.started_at=l.execution_accepted_at
187	  JOIN ui_test_revisions r ON r.id=e.revision_id AND r.test_id=l.test_id AND r.csi_id=l.csi_id
188	  WHERE l.execution_id=execution_key AND e.observed_revision_binding->>'attemptId'=attempt_key::text;
189	 IF jsonb_typeof(declarations) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'terminal secret declaration unavailable'; END IF;
190	 IF jsonb_array_length(declarations)>64 OR EXISTS(SELECT 1 FROM jsonb_array_elements(declarations) name
191	  WHERE jsonb_typeof(name)<>'string' OR name#>>'{}' !~ '^[A-Za-z0-9_.-]{1,64}$')
192	  OR (SELECT count(*) FROM jsonb_array_elements_text(declarations))<>
193	     (SELECT count(DISTINCT name) FROM jsonb_array_elements_text(declarations) name) THEN
194	  RAISE EXCEPTION 'terminal secret declaration invalid'; END IF;
195	 SELECT jsonb_build_object('noReadIds',COALESCE(jsonb_agg(name ORDER BY name) FILTER(WHERE NOT entered),'[]'::jsonb),
196	  'possibleReadIds',COALESCE(jsonb_agg(name ORDER BY name) FILTER(WHERE entered),'[]'::jsonb)) INTO result
197	 FROM (SELECT name,EXISTS(SELECT 1 FROM studio_observed_secret_read_entries entry
198	   WHERE entry.execution_id=execution_key AND entry.attempt_id=attempt_key AND entry.secret_id=name) AS entered
199	  FROM jsonb_array_elements_text(declarations) name
200	  WHERE NOT EXISTS(SELECT 1 FROM studio_secret_use_audit fact WHERE fact.execution_id=execution_key
201	    AND fact.attempt_id=attempt_key::text AND fact.secret_id=name
202	    AND (fact.decision_stage='DISPATCH' OR fact.row_kind='USAGE'))) remaining;
203	 RETURN result;
204	END $$;
