206	CREATE FUNCTION studio_observed_terminal_insert_guard() RETURNS trigger LANGUAGE plpgsql AS $$
207	DECLARE l studio_dispatch_ledger; e ui_test_executions; expected jsonb;
208	BEGIN
209	 SELECT * INTO STRICT l FROM studio_dispatch_ledger WHERE execution_id=NEW.execution_id FOR UPDATE;
210	 SELECT * INTO STRICT e FROM ui_test_executions WHERE id=l.execution_id AND started_at=l.execution_accepted_at FOR UPDATE;
211	 PERFORM pg_advisory_xact_lock(hashtextextended('studio-secret-audit-owner:OBSERVED_REPLAY:'||NEW.execution_id::text,0));
212	 PERFORM pg_advisory_xact_lock(hashtextextended('studio-secret-terminal-id:'||NEW.id::text,0));
213	 IF (l.state IN ('QUEUED','CLAIMED') AND l.attempt_id IS NULL AND l.admission_id IS NULL
214	  AND e.status='PENDING' AND e.observed_admission_receipt IS NULL AND e.observed_revision_binding IS NOT NULL
215	  AND e.observed_revision_binding->>'attemptId'=NEW.attempt_id::text
216	  AND ROW(l.execution_accepted_at,e.revision_id,e.observed_revision_binding->>'revisionDigest',
217	   studio_publication_hash(e.observed_revision_binding),e.observed_revision_binding->>'scopeHash',
218	   l.principal,l.csi_id,e.environment,l.test_id)
219	   IS NOT DISTINCT FROM ROW(NEW.execution_accepted_at,NEW.revision_id,NEW.revision_digest::text,
220	    NEW.binding_digest::text,NEW.scope_hash::text,NEW.principal_id,NEW.csi_id,NEW.environment,NEW.test_id)) IS NOT TRUE THEN
221	  RAISE EXCEPTION 'terminal secret settlement requires authentic pre-transition owner';
222	 END IF;
223	 IF (NEW.before_state IS NOT NULL AND NEW.before_state IS DISTINCT FROM l.state)
224	  OR (NEW.before_updated_at IS NOT NULL AND NEW.before_updated_at IS DISTINCT FROM l.updated_at)
225	  OR (NEW.before_snapshot_revision IS NOT NULL AND NEW.before_snapshot_revision IS DISTINCT FROM e.snapshot_revision)
226	  OR (NEW.before_ended_at IS NOT NULL AND NEW.before_ended_at IS DISTINCT FROM e.ended_at) THEN
227	  RAISE EXCEPTION 'terminal secret settlement before-image mismatch'; END IF;
228	 NEW.before_state:=l.state;NEW.before_updated_at:=l.updated_at;NEW.before_snapshot_revision:=e.snapshot_revision;
229	 NEW.before_ended_at:=e.ended_at;
230	 IF e.ended_at IS NOT NULL THEN NEW.terminal_ended_at:=e.ended_at; END IF;
231	 IF EXISTS(SELECT 1 FROM studio_observed_terminal_secret_settlements existing
232	  WHERE existing.execution_id=NEW.execution_id AND existing.attempt_id=NEW.attempt_id) THEN
233	  RAISE EXCEPTION 'terminal secret settlement duplicate'; END IF;
234	 -- Separate SPI command after lock acquisition, including a writer we waited for.
235	 expected:=studio_observed_terminal_classification(NEW.execution_id,NEW.attempt_id);
236	 IF NEW.no_read_ids IS DISTINCT FROM expected->'noReadIds' OR NEW.possible_read_ids IS DISTINCT FROM expected->'possibleReadIds' THEN
237	  RAISE EXCEPTION 'terminal secret settlement classification mismatch'; END IF;
238	 RETURN NEW;
239	END $$;
240	CREATE TRIGGER tr_observed_terminal_insert BEFORE INSERT ON studio_observed_terminal_secret_settlements
241	 FOR EACH ROW EXECUTE FUNCTION studio_observed_terminal_insert_guard();
