243	CREATE FUNCTION studio_observed_terminal_commit_guard() RETURNS trigger LANGUAGE plpgsql AS $$
244	DECLARE l studio_dispatch_ledger; e ui_test_executions; owner_version xid; history_version xid;
245	 receipt_version xid; usage_version xid; secret text; expected_code text; counts integer;
246	BEGIN
247	 SELECT * INTO STRICT l FROM studio_dispatch_ledger WHERE execution_id=NEW.execution_id;
248	 SELECT xmin INTO owner_version FROM studio_dispatch_ledger WHERE execution_id=NEW.execution_id;
249	 SELECT * INTO STRICT e FROM ui_test_executions WHERE id=l.execution_id AND started_at=l.execution_accepted_at;
250	 SELECT xmin INTO history_version FROM ui_test_executions WHERE id=l.execution_id AND started_at=l.execution_accepted_at;
251	 SELECT xmin INTO receipt_version FROM studio_observed_terminal_secret_settlements WHERE id=NEW.id AND occurred_at=NEW.occurred_at;
252	 IF (owner_version=pg_current_xact_id()::xid AND history_version=pg_current_xact_id()::xid
253	  AND receipt_version=pg_current_xact_id()::xid AND l.state='DONE' AND e.status='ERROR'
254	  AND l.attempt_id IS NULL AND l.admission_id IS NULL AND e.observed_admission_receipt IS NULL
255	  AND e.snapshot_revision=NEW.before_snapshot_revision+1 AND e.error_code=NEW.terminal_error_code
256	  AND e.ended_at=NEW.terminal_ended_at AND l.execution_accepted_at=NEW.execution_accepted_at
257	  AND e.revision_id=NEW.revision_id AND e.observed_revision_binding->>'attemptId'=NEW.attempt_id::text
258	  AND studio_publication_hash(e.observed_revision_binding)=NEW.binding_digest
259	  AND ROW(l.principal,l.csi_id,e.environment,l.test_id,e.observed_revision_binding->>'scopeHash',e.observed_revision_binding->>'revisionDigest')
260	   IS NOT DISTINCT FROM ROW(NEW.principal_id,NEW.csi_id,NEW.environment,NEW.test_id,NEW.scope_hash::text,NEW.revision_digest::text)
261	  AND (l.terminal_error_code IS NULL OR l.terminal_error_code=e.error_code)
262	  AND (l.terminal_error_at IS NULL OR l.terminal_error_at=e.ended_at)) IS NOT TRUE THEN
263	  RAISE EXCEPTION 'terminal secret settlement requires exact top-transaction winner and locator'; END IF;
264	 FOR secret IN SELECT jsonb_array_elements_text(NEW.no_read_ids||NEW.possible_read_ids) LOOP
265	  expected_code:=CASE WHEN NEW.no_read_ids ? secret THEN 'NOT_USED' ELSE 'UNKNOWN_OUTCOME' END;
266	  SELECT count(*) INTO counts FROM studio_secret_use_audit fact WHERE fact.execution_id=NEW.execution_id
267	   AND fact.attempt_id=NEW.attempt_id::text AND fact.secret_id=secret AND fact.row_kind='USAGE'
268	   AND fact.release_id IS NULL AND fact.usage_outcome=expected_code AND fact.release_seq IS NULL
269	   AND fact.outcome IS NULL AND fact.vault_version IS NULL AND fact.admission_id IS NULL
270	   AND fact.coordinate_step_id IS NULL AND fact.coordinate_ordinal IS NULL AND fact.source_reference_id IS NULL;
271	  SELECT xmin INTO usage_version FROM studio_secret_use_audit fact WHERE fact.execution_id=NEW.execution_id
272	   AND fact.attempt_id=NEW.attempt_id::text AND fact.secret_id=secret AND fact.row_kind='USAGE' AND fact.release_id IS NULL;
273	  IF counts<>1 OR usage_version IS DISTINCT FROM pg_current_xact_id()::xid THEN
274	   RAISE EXCEPTION 'terminal secret settlement requires complete top-transaction summaries'; END IF;
275	 END LOOP;
276	 RETURN NEW;
277	END $$;
