290	CREATE FUNCTION studio_observed_secret_evidence_guard() RETURNS trigger LANGUAGE plpgsql AS $$
291	DECLARE l studio_dispatch_ledger; e ui_test_executions; ids jsonb; secret text;
292	BEGIN
293	 SELECT * INTO STRICT l FROM studio_dispatch_ledger WHERE execution_id=NEW.execution_id FOR UPDATE;
294	 SELECT * INTO STRICT e FROM ui_test_executions WHERE id=l.execution_id AND started_at=l.execution_accepted_at FOR UPDATE;
295	 PERFORM pg_advisory_xact_lock(hashtextextended('studio-secret-audit-owner:OBSERVED_REPLAY:'||NEW.execution_id::text,0));
296	 PERFORM pg_advisory_xact_lock(hashtextextended('studio-secret-evidence-id:'||NEW.id::text,0));
297	 IF (l.state='CLAIMED' AND l.attempt_id IS NULL AND l.admission_id IS NULL
298	  AND l.lease_owner=NEW.lease_owner AND l.lease_expires_at>clock_timestamp()
299	  AND e.observed_revision_binding IS NOT NULL AND e.observed_admission_receipt IS NULL
300	  AND e.observed_revision_binding->>'attemptId'=NEW.attempt_id::text
301	  AND ROW(l.execution_accepted_at,e.revision_id,e.observed_revision_binding->>'revisionDigest',
302	   studio_publication_hash(e.observed_revision_binding),e.observed_revision_binding->>'scopeHash',
303	   l.principal,l.csi_id,e.environment,l.test_id)
304	   IS NOT DISTINCT FROM ROW(NEW.execution_accepted_at,NEW.revision_id,NEW.revision_digest::text,
305	    NEW.binding_digest::text,NEW.scope_hash::text,NEW.principal_id,NEW.csi_id,NEW.environment,NEW.test_id)) IS NOT TRUE THEN
306	  RAISE EXCEPTION 'observed secret evidence owner or binding invalid';
307	 END IF;
308	 SELECT r."references"->'secrets' INTO STRICT ids FROM ui_test_revisions r
309	  WHERE r.id=e.revision_id AND r.test_id=l.test_id AND r.csi_id=l.csi_id;
310	 IF jsonb_typeof(ids) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'observed secret declaration unavailable'; END IF;
311	 IF TG_TABLE_NAME LIKE 'studio_observed_secret_read_entries%' THEN
312	  IF EXISTS(SELECT 1 FROM studio_observed_terminal_secret_settlements cut WHERE cut.execution_id=NEW.execution_id) THEN
313	   RAISE EXCEPTION 'terminal secret cut fences new read entry'; END IF;
314	  IF NOT (ids ? NEW.secret_id) OR EXISTS(SELECT 1 FROM studio_observed_secret_read_entries entry
315	   WHERE entry.execution_id=NEW.execution_id AND entry.attempt_id=NEW.attempt_id AND entry.secret_id=NEW.secret_id)
316	   OR EXISTS(SELECT 1 FROM studio_observed_no_send_decisions receipt
317	    WHERE receipt.execution_id=NEW.execution_id AND receipt.attempt_id=NEW.attempt_id) THEN
318	   RAISE EXCEPTION 'observed secret read entry undeclared or duplicate';
319	  END IF;
320	 ELSE
321	  IF jsonb_typeof(NEW.not_entered_ids) IS DISTINCT FROM 'array'
322	   OR jsonb_array_length(NEW.not_entered_ids)>64
323	   OR EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.not_entered_ids) name
324	    WHERE jsonb_typeof(name)<>'string' OR name#>>'{}' !~ '^[A-Za-z0-9_.-]{1,64}$')
325	   OR (SELECT count(*) FROM jsonb_array_elements_text(NEW.not_entered_ids))<>
326	      (SELECT count(DISTINCT name) FROM jsonb_array_elements_text(NEW.not_entered_ids) name)
327	   OR EXISTS(SELECT 1 FROM studio_observed_no_send_decisions receipt
328	    WHERE receipt.execution_id=NEW.execution_id AND receipt.attempt_id=NEW.attempt_id) THEN
329	   RAISE EXCEPTION 'observed no-send receipt shape or identity invalid';
330	  END IF;
331	  FOR secret IN SELECT jsonb_array_elements_text(NEW.not_entered_ids) LOOP
332	   IF NOT (ids ? secret) OR EXISTS(SELECT 1 FROM studio_observed_secret_read_entries entry
333	     WHERE entry.execution_id=NEW.execution_id AND entry.attempt_id=NEW.attempt_id AND entry.secret_id=secret)
334	    OR EXISTS(SELECT 1 FROM studio_secret_use_audit decision WHERE decision.execution_id=NEW.execution_id
335	     AND decision.attempt_id=NEW.attempt_id::text AND decision.secret_id=secret AND decision.decision_stage='DISPATCH') THEN
336	    RAISE EXCEPTION 'observed no-send positive absence contradicted';
337	   END IF;
338	  END LOOP;
339	 END IF;
340	 RETURN NEW;
341	END $$;
