347	CREATE FUNCTION studio_observed_no_send_commit_guard() RETURNS trigger LANGUAGE plpgsql AS $$
348	DECLARE l studio_dispatch_ledger; e ui_test_executions; owner_version xid; secret text;
349	BEGIN
350	 SELECT * INTO STRICT l FROM studio_dispatch_ledger WHERE execution_id=NEW.execution_id;
351	 SELECT xmin INTO owner_version FROM studio_dispatch_ledger WHERE execution_id=NEW.execution_id;
352	 SELECT * INTO STRICT e FROM ui_test_executions WHERE id=l.execution_id AND started_at=l.execution_accepted_at;
353	 IF (owner_version=pg_current_xact_id()::xid AND l.execution_accepted_at=NEW.execution_accepted_at
354	  AND l.attempt_id IS NULL AND l.admission_id IS NULL
355	  AND e.observed_admission_receipt IS NULL AND e.revision_id=NEW.revision_id
356	  AND e.observed_revision_binding->>'attemptId'=NEW.attempt_id::text
357	  AND studio_publication_hash(e.observed_revision_binding)=NEW.binding_digest
358	  AND ((NEW.disposition='CLOSED' AND l.state='DONE' AND e.status='ERROR'
359	    AND l.terminal_error_code=e.error_code AND l.terminal_error_at=e.ended_at
360	    AND (l.lease_owner=NEW.lease_owner OR l.lease_owner IS NULL)) OR
361	   (NEW.disposition='REQUEUED' AND l.state='QUEUED' AND l.lease_owner IS NULL AND l.lease_expires_at IS NULL
362	    AND l.zero_send_decision_attempt_id=NEW.attempt_id
363	    AND EXISTS(SELECT 1 FROM studio_secret_use_audit decision WHERE decision.execution_id=NEW.execution_id
364	     AND decision.attempt_id=NEW.attempt_id::text AND decision.decision_stage='DISPATCH' AND decision.outcome='VAULT_UNAVAILABLE')))) IS NOT TRUE THEN
365	  RAISE EXCEPTION 'observed no-send receipt requires winning atomic owner transition';
366	 END IF;
367	 FOR secret IN SELECT jsonb_array_elements_text(NEW.not_entered_ids) LOOP
368	  IF (SELECT count(*) FROM studio_secret_use_audit usage WHERE usage.execution_id=NEW.execution_id
369	   AND usage.attempt_id=NEW.attempt_id::text AND usage.secret_id=secret AND usage.row_kind='USAGE'
370	   AND usage.release_id IS NULL AND usage.usage_outcome='NOT_USED')<>1 THEN
371	   RAISE EXCEPTION 'observed no-send receipt requires exact unused summary';
372	  END IF;
373	 END LOOP;
374	 RETURN NEW;
375	END $$;
