440	DECLARE original studio_secret_use_audit; s studio_guided_sessions; l studio_dispatch_ledger;
441	 action studio_guided_actions; execution ui_test_executions; actual_reference text;
442	BEGIN
443	 -- Global order: caller owner row, lifecycle owner advisory, event advisory.
444	 IF NEW.path='GUIDED' THEN
445	  SELECT * INTO STRICT s FROM studio_guided_sessions WHERE session_id=NEW.session_id FOR UPDATE;
446	 ELSE
447	  SELECT * INTO STRICT l FROM studio_dispatch_ledger WHERE execution_id=NEW.execution_id FOR UPDATE;
448	 END IF;
449	 -- Serialize the lifecycle across partitions, including duplicate unlinked summaries.
450	 PERFORM pg_advisory_xact_lock(hashtextextended('studio-secret-audit-owner:'||NEW.path||':'||
451	  COALESCE(NEW.session_id,NEW.execution_id::text),0));
452	 -- Caller session/ledger row lock precedes owner, then event; Java uses the same order.
453	 PERFORM pg_advisory_xact_lock(hashtextextended('studio-secret-audit-id:'||NEW.id::text,0));
454	 IF EXISTS(SELECT 1 FROM studio_secret_use_audit WHERE id=NEW.id) THEN
455	  RAISE EXCEPTION 'secret audit identity already exists';
456	 END IF;
457	 IF NEW.path='GUIDED' THEN
458	  SELECT * INTO STRICT s FROM studio_guided_sessions WHERE session_id=NEW.session_id;
459	  IF ROW(s.test_id,s.principal_id,s.document->'scope'->>'csiId',s.document->'scope'->>'environmentId')
460	   IS DISTINCT FROM ROW(NEW.test_id::text,NEW.principal_id,NEW.csi_id,NEW.environment) THEN
461	   RAISE EXCEPTION 'secret audit session scope mismatch';
462	  END IF;
463	  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(s.document->'sourceSteps') step
464	   WHERE step->>'stepId'=NEW.coordinate_step_id) THEN
465	   RAISE EXCEPTION 'secret audit source coordinate mismatch';
466	  END IF;
467	  IF NEW.admission_id IS NOT NULL THEN
468	   SELECT * INTO STRICT action FROM studio_guided_actions
469	    WHERE session_id=NEW.session_id AND admission_id=NEW.admission_id;
470	   IF ROW(action.step_id,action.ordinal) IS DISTINCT FROM ROW(NEW.coordinate_step_id,NEW.coordinate_ordinal)
471	    THEN RAISE EXCEPTION 'secret audit admission coordinate mismatch'; END IF;
472	  END IF;
473	  IF NEW.admission_id IS NOT NULL THEN
474	   actual_reference:=studio_secret_guided_input_reference(NEW.session_id,s.scope_hash,NEW.admission_id);
475	   IF actual_reference IS NULL OR (NEW.source_reference_id IS NOT NULL AND NEW.source_reference_id<>actual_reference) THEN
476	    RAISE EXCEPTION 'secret audit admission source reference declaration lineage invalid';
477	   END IF;
478	  END IF;
479	  IF NEW.decision_stage='DISPATCH' THEN
480	   IF NEW.attempt_id IS DISTINCT FROM NEW.session_id||':'||(s.document->'owner'->>'fence')
481	    OR NOT studio_secret_guided_declaration(NEW.session_id,s.scope_hash,NEW.coordinate_step_id,NEW.secret_id)
482	    OR NOT studio_secret_guided_consumed(NEW.session_id,s.scope_hash,NEW.admission_id,
483	     NEW.coordinate_step_id,NEW.coordinate_ordinal,NEW.secret_id,NEW.attempt_id)
484	    OR EXISTS(SELECT 1 FROM studio_secret_use_audit u WHERE u.session_id=NEW.session_id
485	     AND u.row_kind='USAGE' AND u.release_id IS NULL
486	     AND ((u.usage_outcome='NOT_USED' AND u.source_reference_id=actual_reference) OR u.admission_id=NEW.admission_id)) THEN
487	    RAISE EXCEPTION 'secret audit guided release lineage invalid';
488	   END IF;
489	  END IF;
490	  IF NEW.row_kind='USAGE' AND NEW.release_id IS NULL THEN
491	   IF s.state NOT IN ('FINALIZING','SUCCEEDED','PUBLICATION_CONFLICT','FAILED','UNKNOWN_OUTCOME','CANCELLED','EXPIRED')
492	    OR NOT studio_secret_guided_declaration(NEW.session_id,s.scope_hash,NEW.coordinate_step_id,NEW.secret_id)
493	    OR EXISTS(SELECT 1 FROM studio_secret_use_audit decision
494	     WHERE decision.session_id=NEW.session_id AND decision.secret_id=NEW.secret_id
495	      AND decision.decision_stage='DISPATCH'
496	      AND (NEW.usage_outcome<>'NOT_USED' AND decision.admission_id=NEW.admission_id
497	       OR NEW.usage_outcome='NOT_USED' AND (decision.source_reference_id=NEW.source_reference_id
498	        OR studio_secret_guided_input_reference(NEW.session_id,s.scope_hash,decision.admission_id)=NEW.source_reference_id))) THEN
499	    RAISE EXCEPTION 'secret audit no-decision scope or declaration invalid';
500	   END IF;
501	   IF NEW.usage_outcome='NOT_USED' THEN
